offset matching the next fragment start,\n            // preventing the timeline from shifting.\n            this.warn(\n              `Could not parse fragment ${frag.sn} ${type} duration reliably (${parsedDuration})`,\n            );\n            return result || false;\n          }\n          const drift = chunkMeta.partial\n            ? 0\n            : updateFragPTSDTS(\n                details,\n                frag,\n                info.startPTS,\n                info.endPTS,\n                info.startDTS,\n                info.endDTS,\n                this.iframesOnly,\n                this,\n              );\n          this.hls.trigger(Events.LEVEL_PTS_UPDATED, {\n            details,\n            level,\n            drift,\n            type,\n            frag,\n            start: info.startPTS,\n            end: info.endPTS,\n          });\n          return true;\n        }\n        return result;\n      },\n      false,\n    );\n    if (!parsed) {\n      // The transmuxer error is null when transmuxing completed without error\n      // but found no elementary streams (e.g. an empty segment), and non-null\n      // when an error occurred before any media samples were found.\n      const mediaNotFound = this.transmuxer?.error === null;\n      const transmuxerError = this.transmuxer?.error != null;\n      const hasAlternateLevels = (this.levels?.length ?? 0) > 1;\n      if (\n        level.fragmentError === 0 ||\n        (mediaNotFound && (level.fragmentError < 2 || frag.endList)) ||\n        (transmuxerError && hasAlternateLevels)\n      ) {\n        // Mark and track the empty or errored segment as a gap to avoid\n        // reloading. A fragment with a transmuxer error is only gapped when\n        // alternate levels exist, so playback advances instead of reloading\n        // the same segment after each level switch; with a single level the\n        // error is left to escalate through error-controller retries.\n        this.treatAsGap(frag, level);\n      }\n      if (mediaNotFound) {\n        const error = new Error(\n          `Found no media in ${this.playlistLabel()} ${frag.level} ${\n            part ? `part: ${part.index} of ` : ''\n          }sn: ${frag.sn} at playlist time: ${frag.start}. Resetting transmuxer to fallback to playlist timing`,\n        );\n        this.warn(error.message);\n        this.hls.trigger(Events.ERROR, {\n          type: ErrorTypes.MEDIA_ERROR,\n          details: ErrorDetails.FRAG_PARSING_ERROR,\n          fatal: false,\n          error,\n          frag,\n          reason: `Found no media in msn ${frag.sn} of ${this.playlistLabel()} \"${level.url}\"`,\n        });\n        if (!this.hls) {\n          return;\n        }\n        this.resetTransmuxer();\n      }\n      // For this error fallthrough. Marking parsed will allow advancing to next fragment.\n    }\n    this.state = State.PARSED;\n    this.log(\n      `Parsed ${frag.type} sn: ${frag.sn}${\n        part ? ' part: ' + part.index : ''\n      } of ${this.fragInfo(frag, false, part)}`,\n    );\n    this.hls.trigger(Events.FRAG_PARSED, { frag, part, chunkMeta });\n  }\n\n  private playlistLabel() {\n    return `${this.playlistType} playlist`;\n  }\n\n  private fragInfo(\n    frag: Fragment,\n    pts: boolean = true,\n    part?: Part | null,\n  ): string {\n    return `${this.playlistLabel()} ${frag.level} (${part ? 'part' : 'frag'}:[${(pts && !part ? frag.startPTS : (part || frag).start) ?? NaN}-${\n      (pts && !part ? frag.endPTS : (part || frag).end) ?? NaN\n    }]${part && frag.type === 'main' ? 'INDEPENDENT=' + (part.independent ? 'YES' : 'NO') : ''})`;\n  }\n\n  private treatAsGap(frag: MediaFragment, level?: Level) {\n    if (level) {\n      level.fragmentError++;\n    }\n    this.fragmentTracker.addAsGap(frag);\n  }\n\n  protected resetTransmuxer() {\n    this.transmuxer?.reset();\n  }\n\n  private isFragmentNearlyDownloaded(fragment: Fragment): boolean {\n    const stats = fragment.loader?.stats;\n    if (!stats) {\n      return false;\n    }\n\n    const hasFirstByte = stats.loading.first > 0;\n    const bitsRemaining = stats.total - stats.loaded;\n    const timeToCompleteFragDownload =\n      bitsRemaining /\n      (this.hls.bandwidthEstimate || this.hls.config.abrEwmaDefaultEstimate);\n\n    // Fragment is nearly complete if we have first byte and will complete within 150ms\n    return hasFirstByte && timeToCompleteFragDownload <= 0.15;\n  }\n\n  protected recoverWorkerError(data: ErrorData) {\n    if (data.event === 'demuxerWorker') {\n      this.fragmentTracker.removeAllFragments();\n      if (this.transmuxer) {\n        this.transmuxer.destroy();\n        this.transmuxer = null;\n      }\n      this.resetStartWhenNotLoaded();\n      this.resetLoadingState();\n    }\n  }\n\n  set state(nextState: (typeof State)[keyof typeof State]) {\n    const previousState = this._state;\n    if (previousState !== nextState) {\n      this._state = nextState;\n      this.log(`${previousState}->${nextState}`);\n    }\n  }\n\n  get state(): (typeof State)[keyof typeof State] {\n    return this._state;\n  }\n\n  /**\n   * Calculate optimal switch point by considering fetch delays and buffer info\n   * to avoid causing playback interruption\n   */\n  protected calculateOptimalSwitchPoint(\n    nextLevel: Level,\n    bufferInfo: BufferInfo,\n  ): { fetchdelay: number; okToFlushForwardBuffer: boolean } {\n    let fetchdelay = 0;\n    const { hls, media, config, levels, playlistType } = this;\n    const levelDetails = this.getLevelDetails();\n    if (media && !media.paused && levels) {\n      const maxBitrate =\n        playlistType === PlaylistLevelType.AUDIO\n          ? estimatedAudioBitrate(nextLevel.audioCodec, 128000)\n          : nextLevel.maxBitrate;\n      // add a safety delay of 1s\n      const ttfbSec = 1 + hls.ttfbEstimate / 1000;\n      const bandwidth = hls.bandwidthEstimate * config.abrBandWidthUpFactor;\n      const fragDuration =\n        (levelDetails &&\n          (this.loadingParts\n            ? levelDetails.partTarget\n            : levelDetails.averagetargetduration)) ||\n        this.fragCurrent?.duration ||\n        6;\n      fetchdelay = ttfbSec + (maxBitrate * fragDuration) / bandwidth;\n      if (!nextLevel.details) {\n        fetchdelay += ttfbSec;\n      }\n    }\n\n    const currentTime = this.playhead;\n    // Do not flush in live stream with low buffer\n    const okToFlushForwardBuffer =\n      !levelDetails?.live || bufferInfo.end - currentTime > fetchdelay * 1.5;\n\n    return { fetchdelay, okToFlushForwardBuffer };\n  }\n\n  /**\n   * Generic track switching scheduler that prevents buffering interruptions\n   * by finding optimal flush points in the buffer\n   * This method can be overridden by subclasses with specific implementation details\n   */\n  protected scheduleTrackSwitch(\n    bufferInfo: BufferInfo,\n    fetchdelay: number,\n    okToFlushForwardBuffer: boolean,\n  ): void {\n    const { media, playlistType } = this;\n    if (!media || !bufferInfo) {\n      return;\n    }\n\n    // find buffer range that will be reached once new fragment will be fetched\n    const bufferedFrag = okToFlushForwardBuffer\n      ? this.getBufferedFrag(this.playhead + fetchdelay)\n      : null;\n\n    if (bufferedFrag) {\n      // we can flush buffer range following this one without stalling playback\n      const nextBufferedFrag = this.followingBufferedFrag(bufferedFrag);\n      if (nextBufferedFrag) {\n        // if we are here, we can also cancel any loading/demuxing in progress, as they are useless\n        this.abortCurrentFrag();\n        // start flush position is in next buffered frag. Leave some padding for non-independent segments and smoother playback.\n        const maxStart = nextBufferedFrag.maxStartPTS\n          ? nextBufferedFrag.maxStartPTS\n          : nextBufferedFrag.start;\n        const fragDuration = nextBufferedFrag.duration;\n        const startOffset = Math.max(\n          bufferedFrag.end,\n          maxStart +\n            Math.min(\n              Math.max(\n                fragDuration - this.config.maxFragLookUpTolerance,\n                fragDuration * (this.couldBacktrack ? 0.5 : 0.125),\n              ),\n              fragDuration * (this.couldBacktrack ? 0.75 : 0.25),\n            ),\n        );\n\n        // If behind the live window, do not remove buffered media\n        const liveWindowStart = this.getLevelDetails()?.fragmentStart || 0;\n        if (liveWindowStart > startOffset) {\n          return;\n        }\n\n        const bufferType =\n          playlistType === PlaylistLevelType.MAIN ? null : 'audio';\n        // Flush forward buffer from next buffered frag start to infinity\n        this.flushMainBuffer(startOffset, Number.POSITIVE_INFINITY, bufferType);\n\n        // Flush back buffer (excluding current fragment)\n        this.cleanupBackBuffer();\n      }\n    }\n  }\n\n  /**\n   * Handle back-buffer cleanup during track switching\n   */\n  protected cleanupBackBuffer(): void {\n    const { media, playlistType } = this;\n    if (!media) {\n      return;\n    }\n\n    // remove back-buffer\n    const fragPlayingCurrent = this.getAppendedFrag(this.playhead);\n    if (fragPlayingCurrent && fragPlayingCurrent.start > 1) {\n      const isAudio = playlistType === PlaylistLevelType.AUDIO;\n      // flush buffer preceding current fragment (flush until current fragment start offset)\n      // minus 1s to avoid video freezing, that could happen if we flush keyframe of current video ...\n      this.flushMainBuffer(\n        0,\n        fragPlayingCurrent.start - (isAudio ? 0 : 1),\n        isAudio ? 'audio' : null,\n      );\n    }\n  }\n\n  /**\n   * Gets buffered fragment at the specified position\n   */\n  protected getBufferedFrag(position: number): Fragment | null {\n    return this.fragmentTracker.getBufferedFrag(position, this.playlistType);\n  }\n\n  /**\n   * Gets the next buffered fragment following the given fragment\n   */\n  protected followingBufferedFrag(frag: Fragment | null): Fragment | null {\n    if (frag) {\n      // try to get range of next fragment (500ms after this range)\n      return this.getBufferedFrag(frag.end + 0.5);\n    }\n    return null;\n  }\n\n  /**\n   * Aborts the current fragment loading and resets state\n   * Can be overridden by subclasses for specific behavior\n   */\n  protected abortCurrentFrag(): void {\n    const fragCurrent = this.fragCurrent;\n    this.fragCurrent = null;\n    if (fragCurrent) {\n      fragCurrent.abortRequests();\n      this.fragmentTracker.removeFragment(fragCurrent);\n    }\n    switch (this.state) {\n      case State.KEY_LOADING:\n      case State.FRAG_LOADING:\n      case State.FRAG_LOADING_WAITING_RETRY:\n      case State.PARSING:\n      case State.PARSED:\n        this.state = State.IDLE;\n        break;\n    }\n    this.nextLoadPosition = this.playhead;\n  }\n\n  protected checkFragPlaying(): boolean {\n    const video = this.media;\n    let fragPlayingCurrent: MediaFragment | null = null;\n    if (video && video.readyState > 1 && video.seeking === false) {\n      const currentTime = video.currentTime;\n      /* if video element is in seeked state, currentTime can only increase.\n          (assuming that playback rate is positive ...)\n          As sometimes currentTime jumps back to zero after a\n          media decode error, check this, to avoid seeking back to\n          wrong position after a media decode error\n        */\n\n      if (BufferHelper.isBuffered(video, currentTime)) {\n        fragPlayingCurrent = this.getAppendedFrag(currentTime);\n      } else if (BufferHelper.isBuffered(video, currentTime + 0.1)) {\n        /* ensure that FRAG_CHANGED event is triggered at startup,\n            when first video frame is displayed and playback is paused.\n            add a tolerance of 100ms, in case current position is not buffered,\n            check if current pos+100ms is buffered and use that buffer range\n            for FRAG_CHANGED event reporting */\n        fragPlayingCurrent = this.getAppendedFrag(currentTime + 0.1);\n      }\n      if (fragPlayingCurrent) {\n        this.backtrackFragment = undefined;\n        if (!mediaFragmentsAreEqual(fragPlayingCurrent, this.fragPlaying)) {\n          this.fragPlaying = fragPlayingCurrent;\n          return true;\n        }\n      }\n    }\n    return false;\n  }\n\n  protected getBufferOutput(): Bufferable | null {\n    return null;\n  }\n\n  /**\n   * try to switch ASAP without breaking video playback:\n   * in order to ensure smooth but quick level switching,\n   * we need to find the next flushable buffer range\n   * we should take into account new segment fetch time\n   */\n  public nextLevelSwitch() {\n    const { levels, media, hls, config, playlistType } = this;\n    // ensure that media is defined and that metadata are available (to retrieve currentTime)\n    if (media?.readyState && levels && hls && config) {\n      const bufferOutput = this.getBufferOutput();\n      const bufferInfo = this.getFwdBufferInfo(bufferOutput, playlistType);\n      if (!bufferInfo) {\n        return;\n      }\n\n      const nextLevelId =\n        playlistType === PlaylistLevelType.AUDIO\n          ? hls.nextAudioTrack\n          : hls.nextLoadLevel;\n      const nextLevel = levels[nextLevelId];\n\n      const { fetchdelay, okToFlushForwardBuffer } =\n        this.calculateOptimalSwitchPoint(nextLevel, bufferInfo);\n\n      this.scheduleTrackSwitch(bufferInfo, fetchdelay, okToFlushForwardBuffer);\n    }\n    this.tickImmediate();\n  }\n}\n\nexport function fragOverlapsQueuedInterstitial(\n  frag: MediaFragment | Part,\n  playerQueue: HlsAssetPlayer[] | undefined,\n  playhead: number,\n): boolean {\n  if (__USE_INTERSTITIALS__ && playerQueue) {\n    for (let i = playerQueue.length; i--; ) {\n      const interstitial = playerQueue[i].interstitial;\n      const start = interstitial.startTime;\n      const end = Math.min(\n        start + interstitial.duration,\n        interstitial.resumeTime,\n      );\n      if (interstitial.appendInPlace) {\n        if (frag.start >= start && frag.end <= end) {\n          return true;\n        }\n        if (playhead > frag.start && frag.end > start && frag.start < end) {\n          return true;\n        }\n      }\n    }\n  }\n  return false;\n}\n\nexport function interstitialsEnabled(config: Readonly<HlsConfig>): boolean {\n  return (\n    __USE_INTERSTITIALS__ &&\n    !!config.interstitialsController &&\n    config.enableInterstitialPlayback !== false\n  );\n}\n","import type {\n  BufferOperation,\n  BufferOperationQueues,\n  SourceBufferName,\n  SourceBufferTrackSet,\n} from '../types/buffer';\n\nexport default class BufferOperationQueue {\n  private tracks: SourceBufferTrackSet | null;\n  private queues: BufferOperationQueues | null = {\n    video: [],\n    audio: [],\n    audiovideo: [],\n  };\n\n  constructor(sourceBufferReference: SourceBufferTrackSet) {\n    this.tracks = sourceBufferReference;\n  }\n\n  public destroy() {\n    this.tracks = this.queues = null;\n  }\n\n  public append(\n    operation: BufferOperation,\n    type: SourceBufferName,\n    pending?: boolean | undefined,\n  ) {\n    if (this.queues === null || this.tracks === null) {\n      return;\n    }\n    const queue = this.queues[type];\n    queue.push(operation);\n    if (queue.length === 1 && !pending) {\n      this.executeNext(type);\n    }\n  }\n\n  public appendBlocker(type: SourceBufferName): Promise<void> {\n    return new Promise((resolve) => {\n      const operation: BufferOperation = {\n        label: 'async-blocker',\n        execute: resolve,\n        onStart: () => {},\n        onComplete: () => {},\n        onError: () => {},\n      };\n      this.append(operation, type);\n    });\n  }\n\n  public prependBlocker(type: SourceBufferName): Promise<void> {\n    return new Promise((resolve) => {\n      if (this.queues) {\n        const operation: BufferOperation = {\n          label: 'async-blocker-prepend',\n          execute: resolve,\n          onStart: () => {},\n          onComplete: () => {},\n          onError: () => {},\n        };\n        this.queues[type].unshift(operation);\n      }\n    });\n  }\n\n  public removeBlockers() {\n    if (this.queues === null) {\n      return;\n    }\n    [this.queues.video, this.queues.audio, this.queues.audiovideo].forEach(\n      (queue) => {\n        const label = queue[0]?.label;\n        if (label === 'async-blocker' || label === 'async-blocker-prepend') {\n          queue[0].execute();\n          queue.splice(0, 1);\n        } else if (label === 'block-audio') {\n          queue.splice(0, 1);\n        }\n      },\n    );\n  }\n\n  public insertNext(operations: BufferOperation[], type: SourceBufferName) {\n    if (this.queues === null) {\n      return;\n    }\n    // Insert after the current (index 0) operation so they execute next\n    this.queues[type].splice(1, 0, ...operations);\n  }\n\n  public unblockAudio() {\n    if (this.queues === null) {\n      return;\n    }\n    if (this.current('audio')?.label === 'block-audio') {\n      this.shiftAndExecuteNext('audio');\n    }\n  }\n\n  public audioBlocking(): boolean {\n    if (this.queues === null) {\n      return false;\n    }\n    return this.queues.audio.some((op) => op.label === 'block-audio');\n  }\n\n  public executeNext(type: SourceBufferName) {\n    if (this.queues === null || this.tracks === null) {\n      return;\n    }\n    const queue = this.queues[type];\n    if (queue.length) {\n      const operation: BufferOperation = queue[0];\n      try {\n        // Operations are expected to result in an 'updateend' event being fired. If not, the queue will lock. Operations\n        // which do not end with this event must call _onSBUpdateEnd manually\n        operation.execute();\n      } catch (error) {\n        operation.onError(error);\n        if (this.queues === null || this.tracks === null) {\n          return;\n        }\n\n        // Only shift the current operation off, otherwise the updateend handler will do this for us\n        const sb = this.tracks[type]?.buffer;\n        if (!sb?.updating) {\n          this.shiftAndExecuteNext(type);\n        }\n      }\n    }\n  }\n\n  public shiftAndExecuteNext(type: SourceBufferName) {\n    if (this.queues === null) {\n      return;\n    }\n    this.queues[type].shift();\n    this.executeNext(type);\n  }\n\n  public current(type: SourceBufferName): BufferOperation | null {\n    return this.queues?.[type][0] || null;\n  }\n\n  public toString(): string {\n    const { queues, tracks } = this;\n    if (queues === null || tracks === null) {\n      return `<destroyed>`;\n    }\n    return `\n${this.list('video')}\n${this.list('audio')}\n${this.list('audiovideo')}}`;\n  }\n\n  public list(type: SourceBufferName): string {\n    return this.queues?.[type] || this.tracks?.[type]\n      ? `${type}: (${this.listSbInfo(type)}) ${this.listOps(type)}`\n      : '';\n  }\n\n  private listSbInfo(type: SourceBufferName): string {\n    const track = this.tracks?.[type];\n    const sb = track?.buffer;\n    if (!sb) {\n      return 'none';\n    }\n    return `SourceBuffer${sb.updating ? ' updating' : ''}${track.ended ? ' ended' : ''}${track.ending ? ' ending' : ''}`;\n  }\n\n  private listOps(type: SourceBufferName): string {\n    return this.queues?.[type].map((op) => op.label).join(', ') || '';\n  }\n}\n","import BufferOperationQueue from './buffer-operation-queue';\nimport { createDoNothingErrorAction } from './error-controller';\nimport { ErrorDetails, ErrorTypes } from '../errors';\nimport { Events } from '../events';\nimport { ElementaryStreamTypes, isMediaFragment } from '../loader/fragment';\nimport { DEFAULT_TARGET_DURATION } from '../loader/level-details';\nimport { PlaylistLevelType } from '../types/loader';\nimport { BufferHelper, type BufferTimeRange } from '../utils/buffer-helper';\nimport {\n  areCodecsMediaSourceSupported,\n  getCodecCompatibleName,\n  pickMostCompleteCodecName,\n  replaceVideoCodec,\n} from '../utils/codecs';\nimport {\n  addEventListener,\n  removeEventListener,\n} from '../utils/event-listener-helper';\nimport { Logger } from '../utils/logger';\nimport {\n  getMediaSource,\n  isCompatibleTrackChange,\n  isManagedMediaSource,\n} from '../utils/mediasource-helper';\nimport { stringify } from '../utils/safe-json-stringify';\nimport { timeRangesToString } from '../utils/time-ranges';\nimport type { FragmentTracker } from './fragment-tracker';\nimport type { HlsConfig } from '../config';\nimport type Hls from '../hls';\nimport type { Fragment, MediaFragment, Part } from '../loader/fragment';\nimport type { LevelDetails } from '../loader/level-details';\nimport type { LoadStats } from '../loader/load-stats';\nimport type {\n  AttachMediaSourceData,\n  BaseTrack,\n  BaseTrackSet,\n  BufferCreatedTrackSet,\n  BufferOperation,\n  EmptyTuple,\n  ExtendedSourceBuffer,\n  MediaOverrides,\n  ParsedTrack,\n  SourceBufferName,\n  SourceBuffersTuple,\n  SourceBufferTrack,\n  SourceBufferTrackSet,\n} from '../types/buffer';\nimport type { ComponentAPI } from '../types/component-api';\nimport type {\n  BufferAppendingData,\n  BufferCodecsData,\n  BufferEOSData,\n  BufferFlushingData,\n  ErrorData,\n  FragChangedData,\n  FragParsedData,\n  LevelUpdatedData,\n  ManifestParsedData,\n  MediaAttachingData,\n  MediaDetachingData,\n} from '../types/events';\nimport type { ChunkMetadata } from '../types/transmuxer';\n\ninterface BufferedChangeEvent extends Event {\n  readonly addedRanges?: TimeRanges;\n  readonly removedRanges?: TimeRanges;\n}\n\nconst VIDEO_CODEC_PROFILE_REPLACE =\n  /(avc[1234]|hvc1|hev1|dvh[1e]|vp09|av01)(?:\\.[^.,]+)+/;\n\nconst TRACK_REMOVED_ERROR_NAME = 'HlsJsTrackRemovedError';\n\nconst LOOP_FLUSH_SAFETY_MARGIN = 0.25;\n\nconst MIN_BUFFERED_PROGRESS = 0.001;\n\ntype FragmentAppendProgress = {\n  stats: LoadStats;\n  progressed: boolean;\n  errored: boolean;\n  fullyBuffered: Partial<Record<SourceBufferName, boolean>>;\n};\n\nclass HlsJsTrackRemovedError extends Error {\n  constructor(message) {\n    super(message);\n    this.name = TRACK_REMOVED_ERROR_NAME;\n  }\n}\n\nexport default class BufferController extends Logger implements ComponentAPI {\n  private hls: Hls;\n  private fragmentTracker: FragmentTracker;\n  // Track per-load SourceBuffer growth and consecutive no-progress cycles.\n  private fragmentAppendProgress: Partial<\n    Record<string, FragmentAppendProgress>\n  > = Object.create(null);\n  private appendsWithoutProgress: Partial<Record<string, number>> =\n    Object.create(null);\n  // The level details used to determine duration, target-duration and live\n  private details: LevelDetails | null = null;\n  // cache the self generated object url to detect hijack of video tag\n  private _objectUrl: string | null = null;\n  // A queue of buffer operations which require the SourceBuffer to not be updating upon execution\n  private operationQueue: BufferOperationQueue | null = null;\n\n  // The total number track codecs expected before any sourceBuffers are created (2: audio and video or 1: audiovideo | audio | video)\n  private bufferCodecEventsTotal: number = 0;\n\n  // A reference to the attached media element\n  private media: HTMLMediaElement | null = null;\n\n  // A reference to the active media source\n  private mediaSource: MediaSource | null = null;\n\n  // Last MP3 audio chunk appended\n  private lastMpegAudioChunk: ChunkMetadata | null = null;\n\n  // Keep track of video append position for unblocking audio\n  private lastVideoAppendEnd: number = 0;\n  // Whether or not to use ManagedMediaSource API and append source element to media element.\n  private appendSource: boolean;\n  // Transferred MediaSource information used to detmerine if duration end endstream may be appended\n  private transferData?: MediaAttachingData;\n  // Directives used to override default MediaSource handling\n  private overrides?: MediaOverrides;\n  // Error counters\n  private appendErrors = {\n    audio: 0,\n    video: 0,\n    audiovideo: 0,\n  };\n  private appendError?: ErrorData;\n  // Tracks whether a QuotaExceededError back-buffer eviction is in progress for a given SourceBuffer type.\n  private _quotaEvictionPending: Partial<Record<SourceBufferName, boolean>> =\n    {};\n  // Record of required or created buffers by type. SourceBuffer is stored in Track.buffer once created.\n  private tracks: SourceBufferTrackSet = {};\n  // Array of SourceBuffer type and SourceBuffer (or null). One entry per TrackSet in this.tracks.\n  private sourceBuffers: SourceBuffersTuple = [\n    [null, null],\n    [null, null],\n  ];\n\n  constructor(hls: Hls, fragmentTracker: FragmentTracker) {\n    super('buffer-controller', hls.logger);\n    this.hls = hls;\n    this.fragmentTracker = fragmentTracker;\n    this.appendSource = isManagedMediaSource(\n      getMediaSource(hls.config.preferManagedMediaSource),\n    );\n\n    this.initTracks();\n    this.registerListeners();\n  }\n\n  public hasSourceTypes(): boolean {\n    return Object.keys(this.tracks).length > 0;\n  }\n\n  public destroy() {\n    this.unregisterListeners();\n    this.details = null;\n    this.lastMpegAudioChunk = null;\n    this.transferData = this.overrides = undefined;\n    if (this.operationQueue) {\n      this.operationQueue.destroy();\n      this.operationQueue = null;\n    }\n    // @ts-ignore\n    this.hls = this.fragmentTracker = null;\n    // @ts-ignore\n    this._onMediaSourceOpen = this._onMediaSourceClose = null;\n    // @ts-ignore\n    this._onMediaSourceEnded = null;\n    // @ts-ignore\n    this._onStartStreaming = this._onEndStreaming = null;\n    // @ts-ignore\n    this._onMediaEmptied = this._onMediaError = null;\n  }\n\n  private registerListeners() {\n    const { hls } = this;\n    hls.on(Events.MEDIA_ATTACHING, this.onMediaAttaching, this);\n    hls.on(Events.MEDIA_DETACHING, this.onMediaDetaching, this);\n    hls.on(Events.MANIFEST_LOADING, this.onManifestLoading, this);\n    hls.on(Events.MANIFEST_PARSED, this.onManifestParsed, this);\n    hls.on(Events.BUFFER_RESET, this.onBufferReset, this);\n    hls.on(Events.BUFFER_APPENDING, this.onBufferAppending, this);\n    hls.on(Events.BUFFER_CODECS, this.onBufferCodecs, this);\n    hls.on(Events.BUFFER_EOS, this.onBufferEos, this);\n    hls.on(Events.BUFFER_FLUSHING, this.onBufferFlushing, this);\n    hls.on(Events.LEVEL_UPDATED, this.onLevelUpdated, this);\n    hls.on(Events.FRAG_PARSED, this.onFragParsed, this);\n    hls.on(Events.FRAG_CHANGED, this.onFragChanged, this);\n    hls.on(Events.ERROR, this.onError, this);\n  }\n\n  private unregisterListeners() {\n    const { hls } = this;\n    hls.off(Events.MEDIA_ATTACHING, this.onMediaAttaching, this);\n    hls.off(Events.MEDIA_DETACHING, this.onMediaDetaching, this);\n    hls.off(Events.MANIFEST_LOADING, this.onManifestLoading, this);\n    hls.off(Events.MANIFEST_PARSED, this.onManifestParsed, this);\n    hls.off(Events.BUFFER_RESET, this.onBufferReset, this);\n    hls.off(Events.BUFFER_APPENDING, this.onBufferAppending, this);\n    hls.off(Events.BUFFER_CODECS, this.onBufferCodecs, this);\n    hls.off(Events.BUFFER_EOS, this.onBufferEos, this);\n    hls.off(Events.BUFFER_FLUSHING, this.onBufferFlushing, this);\n    hls.off(Events.LEVEL_UPDATED, this.onLevelUpdated, this);\n    hls.off(Events.FRAG_PARSED, this.onFragParsed, this);\n    hls.off(Events.FRAG_CHANGED, this.onFragChanged, this);\n    hls.off(Events.ERROR, this.onError, this);\n  }\n\n  public transferMedia(): AttachMediaSourceData | null {\n    const { media, mediaSource } = this;\n    if (!media) {\n      return null;\n    }\n    const tracks = {};\n    if (this.operationQueue) {\n      const updating = this.isUpdating();\n      if (!updating) {\n        this.operationQueue.removeBlockers();\n      }\n      const queued = this.isQueued();\n      if (updating || queued) {\n        this.warn(\n          `Transfering MediaSource with${queued ? ' operations in queue' : ''}${updating ? ' updating SourceBuffer(s)' : ''} ${this.operationQueue}`,\n        );\n      }\n      this.operationQueue.destroy();\n    }\n    const transferData = this.transferData;\n    if (\n      transferData &&\n      !this.sourceBufferCount &&\n      transferData.mediaSource === mediaSource\n    ) {\n      Object.assign(tracks, transferData.tracks);\n    } else {\n      this.sourceBuffers.forEach((tuple) => {\n        const [type] = tuple;\n        if (type) {\n          tracks[type] = Object.assign({}, this.tracks[type]);\n          this.removeBuffer(type);\n        }\n        tuple[0] = tuple[1] = null;\n      });\n    }\n    return {\n      media,\n      mediaSource,\n      tracks,\n    };\n  }\n\n  private initTracks() {\n    const tracks = {};\n    this.resetAppendProgress();\n    this.sourceBuffers = [\n      [null, null],\n      [null, null],\n    ];\n    this.tracks = tracks;\n    this.resetQueue();\n    this.lastMpegAudioChunk = null;\n    this.lastVideoAppendEnd = 0;\n  }\n\n  private onManifestLoading() {\n    this.bufferCodecEventsTotal = 0;\n    this.details = null;\n    this.resetAppendErrors();\n    this.resetAppendProgress();\n  }\n\n  private onManifestParsed(\n    event: Events.MANIFEST_PARSED,\n    data: ManifestParsedData,\n  ) {\n    // in case of alt audio 2 BUFFER_CODECS events will be triggered, one per stream controller\n    // sourcebuffers will be created all at once when the expected nb of tracks will be reached\n    // in case alt audio is not used, only one BUFFER_CODEC event will be fired from main stream controller\n    // it will contain the expected nb of source buffers, no need to compute it\n    let codecEvents: number = 2;\n    if ((data.audio && !data.video) || !data.altAudio) {\n      codecEvents = 1;\n    }\n    this.bufferCodecEventsTotal = codecEvents;\n    this.log(`${codecEvents} bufferCodec event(s) expected.`);\n    if (\n      this.transferData?.mediaSource &&\n      this.sourceBufferCount &&\n      codecEvents\n    ) {\n      this.bufferCreated();\n    }\n  }\n\n  private onMediaAttaching(\n    event: Events.MEDIA_ATTACHING,\n    data: MediaAttachingData,\n  ) {\n    const media = (this.media = data.media);\n    this.transferData = this.overrides = undefined;\n    const MediaSource = getMediaSource(this.appendSource);\n    if (MediaSource) {\n      const transferringMedia = !!data.mediaSource;\n      if (transferringMedia || data.overrides) {\n        this.transferData = data;\n        this.overrides = data.overrides;\n      }\n      const ms = (this.mediaSource = data.mediaSource || new MediaSource());\n      this.assignMediaSource(ms);\n      if (transferringMedia) {\n        this._objectUrl = media.src;\n        this.attachTransferred();\n      } else {\n        // cache the locally generated object url\n        const objectUrl = (this._objectUrl = self.URL.createObjectURL(ms));\n        // link video and media Source\n        if (this.appendSource) {\n          try {\n            media.removeAttribute('src');\n            // ManagedMediaSource will not open without disableRemotePlayback set to false or source alternatives\n            const MMS = (self as any).ManagedMediaSource;\n            media.disableRemotePlayback =\n              media.disableRemotePlayback || (MMS && ms instanceof MMS);\n            removeSourceChildren(media);\n            addSource(media, objectUrl);\n            media.load();\n          } catch (error) {\n            media.src = objectUrl;\n          }\n        } else {\n          media.src = objectUrl;\n        }\n      }\n      addEventListener(media, 'emptied', this._onMediaEmptied);\n      addEventListener(media, 'error', this._onMediaError);\n      if (this.appendSource) {\n        // Resume streaming on seeking (https://bugs.webkit.org/show_bug.cgi?id=321919)\n        addEventListener(media, 'seeking', this._onStartStreaming);\n      }\n    }\n  }\n\n  private assignMediaSource(ms: MediaSource) {\n    this.log(\n      `${this.transferData?.mediaSource === ms ? 'transferred' : 'created'} media source: ${(ms.constructor as any)?.name}`,\n    );\n    // MediaSource listeners are arrow functions with a lexical scope, and do not need to be bound\n    addEventListener(ms, 'sourceopen', this._onMediaSourceOpen);\n    addEventListener(ms, 'sourceended', this._onMediaSourceEnded);\n    addEventListener(ms, 'sourceclose', this._onMediaSourceClose);\n\n    if (this.appendSource) {\n      addEventListener(ms, 'startstreaming', this._onStartStreaming);\n      addEventListener(ms, 'endstreaming', this._onEndStreaming);\n    }\n  }\n\n  private attachTransferred() {\n    const media = this.media;\n    const data = this.transferData;\n    if (!data || !media) {\n      return;\n    }\n    const requiredTracks = this.tracks;\n    const transferredTracks = data.tracks;\n    const trackNames = transferredTracks\n      ? Object.keys(transferredTracks)\n      : null;\n    const trackCount = trackNames ? trackNames.length : 0;\n    const mediaSourceOpenCallback = () => {\n      // eslint-disable-next-line @typescript-eslint/no-floating-promises\n      Promise.resolve().then(() => {\n        if (this.media && this.mediaSourceOpenOrEnded) {\n          this._onMediaSourceOpen();\n        }\n      });\n    };\n    if (transferredTracks && trackNames && trackCount) {\n      if (!this.tracksReady) {\n        // Wait for CODECS event(s)\n        this.hls.config.startFragPrefetch = true;\n        this.log(`attachTransferred: waiting for SourceBuffer track info`);\n        return;\n      }\n      this\n        .log(`attachTransferred: (bufferCodecEventsTotal ${this.bufferCodecEventsTotal})\nrequired tracks: ${stringify(requiredTracks, (key, value) => (key === 'initSegment' ? undefined : value))};\ntransfer tracks: ${stringify(transferredTracks, (key, value) => (key === 'initSegment' ? undefined : value))}}`);\n      if (!isCompatibleTrackChange(transferredTracks, requiredTracks)) {\n        // destroy attaching media source\n        data.mediaSource = null;\n        data.tracks = undefined;\n\n        const currentTime = media.currentTime;\n\n        const details = this.details;\n        const startTime = Math.max(\n          currentTime,\n          details?.fragments[0].start || 0,\n        );\n        if (startTime - currentTime > 1) {\n          this.log(\n            `attachTransferred: waiting for playback to reach new tracks start time ${currentTime} -> ${startTime}`,\n          );\n          return;\n        }\n        this.warn(\n          `attachTransferred: resetting MediaSource for incompatible tracks (\"${Object.keys(transferredTracks)}\"->\"${Object.keys(requiredTracks)}\") start time: ${startTime} currentTime: ${currentTime}`,\n        );\n        this.onMediaDetaching(Events.MEDIA_DETACHING, {});\n        this.onMediaAttaching(Events.MEDIA_ATTACHING, data);\n        media.currentTime = startTime;\n        return;\n      }\n      this.transferData = undefined;\n      trackNames.forEach((trackName) => {\n        const type = trackName as SourceBufferName;\n        const track = transferredTracks[type];\n        if (track) {\n          const sb = track.buffer;\n          if (sb) {\n            // Purge fragment tracker of ejected segments for existing buffer\n            const fragmentTracker = this.fragmentTracker;\n            const playlistType = track.id as PlaylistLevelType;\n            if (\n              fragmentTracker.hasFragments(playlistType) ||\n              fragmentTracker.hasParts(playlistType)\n            ) {\n              const bufferedTimeRanges = BufferHelper.getBuffered(sb);\n              fragmentTracker.detectEvictedFragments(\n                type,\n                bufferedTimeRanges,\n                playlistType,\n                null,\n                null,\n                true,\n              );\n            }\n            // Transfer SourceBuffer\n            const sbIndex = sourceBufferNameToIndex(type);\n            const sbTuple = [type, sb] as Exclude<\n              SourceBuffersTuple[typeof sbIndex],\n              EmptyTuple\n            >;\n            this.sourceBuffers[sbIndex] = sbTuple as any;\n            if (sb.updating && this.operationQueue) {\n              // eslint-disable-next-line @typescript-eslint/no-floating-promises\n              this.operationQueue.prependBlocker(type);\n            }\n            this.trackSourceBuffer(type, track);\n          }\n        }\n      });\n      mediaSourceOpenCallback();\n      this.bufferCreated();\n    } else {\n      this.log(`attachTransferred: MediaSource w/o SourceBuffers`);\n      mediaSourceOpenCallback();\n    }\n  }\n\n  private get mediaSourceOpenOrEnded(): boolean {\n    const readyState = this.mediaSource?.readyState;\n    return readyState === 'open' || readyState === 'ended';\n  }\n\n  private _onEndStreaming = (event) => {\n    if (!this.hls as any) {\n      return;\n    }\n    if (this.mediaSource?.readyState !== 'open') {\n      return;\n    }\n    if (!this.media || this.media.seeking) {\n      // Ignore ManagedMediaSource while seeking (https://bugs.webkit.org/show_bug.cgi?id=321919)\n      return;\n    }\n    this.hls.pauseBuffering();\n  };\n\n  private _onStartStreaming = (event) => {\n    if (!this.hls as any) {\n      return;\n    }\n    this.hls.resumeBuffering();\n  };\n\n  private onMediaDetaching(\n    event: Events.MEDIA_DETACHING,\n    data: MediaDetachingData,\n  ) {\n    const transferringMedia = !!data.transferMedia;\n    this.transferData = this.overrides = undefined;\n    const { media, mediaSource, _objectUrl } = this;\n    if (mediaSource) {\n      this.log(\n        `media source ${transferringMedia ? 'transferring' : 'detaching'}`,\n      );\n      if (transferringMedia) {\n        // Detach SourceBuffers without removing from MediaSource\n        // and leave `tracks` (required SourceBuffers configuration)\n        this.sourceBuffers.forEach(([type]) => {\n          if (type) {\n            this.removeBuffer(type);\n          }\n        });\n        this.resetQueue();\n      } else {\n        if (this.mediaSourceOpenOrEnded) {\n          const open = mediaSource.readyState === 'open';\n          try {\n            const sourceBuffers = mediaSource.sourceBuffers;\n            for (let i = sourceBuffers.length; i--; ) {\n              if (open) {\n                sourceBuffers[i].abort();\n              }\n              mediaSource.removeSourceBuffer(sourceBuffers[i]);\n            }\n            if (open) {\n              // endOfStream could trigger exception if any sourcebuffer is in updating state\n              // we don't really care about checking sourcebuffer state here,\n              // as we are anyway detaching the MediaSource\n              // let's just avoid this exception to propagate\n              mediaSource.endOfStream();\n            }\n          } catch (err) {\n            this.warn(\n              `onMediaDetaching: ${err.message} while calling endOfStream`,\n            );\n          }\n        }\n        // Clean up the SourceBuffers by invoking onBufferReset\n        if (this.sourceBufferCount) {\n          this.onBufferReset();\n        }\n      }\n      removeEventListener(mediaSource, 'sourceopen', this._onMediaSourceOpen);\n      removeEventListener(mediaSource, 'sourceended', this._onMediaSourceEnded);\n      removeEventListener(mediaSource, 'sourceclose', this._onMediaSourceClose);\n      if (this.appendSource) {\n        removeEventListener(\n          mediaSource,\n          'startstreaming',\n          this._onStartStreaming,\n        );\n        removeEventListener(mediaSource, 'endstreaming', this._onEndStreaming);\n      }\n\n      this.mediaSource = null;\n      this._objectUrl = null;\n    }\n\n    // Detach properly the MediaSource from the HTMLMediaElement as\n    // suggested in https://github.com/w3c/media-source/issues/53.\n    if (media) {\n      removeEventListener(media, 'emptied', this._onMediaEmptied);\n      removeEventListener(media, 'error', this._onMediaError);\n      removeEventListener(media, 'seeking', this._onStartStreaming);\n      if (!transferringMedia) {\n        if (_objectUrl) {\n          self.URL.revokeObjectURL(_objectUrl);\n        }\n\n        // clean up video tag src only if it's our own url. some external libraries might\n        // hijack the video tag and change its 'src' without destroying the Hls instance first\n        if (this.mediaSrc === _objectUrl) {\n          media.removeAttribute('src');\n          if (this.appendSource) {\n            removeSourceChildren(media);\n          }\n          media.load();\n        } else {\n          this.warn(\n            'media|source.src was changed by a third party - skip cleanup',\n          );\n        }\n      }\n      this.media = null;\n    }\n  }\n\n  private onBufferReset() {\n    this.sourceBuffers.forEach(([type]) => {\n      if (type) {\n        this.resetBuffer(type);\n      }\n    });\n    this.initTracks();\n  }\n\n  private resetBuffer(type: SourceBufferName) {\n    const sb = this.tracks[type]?.buffer;\n    this.removeBuffer(type);\n    if (sb) {\n      try {\n        if (this.mediaSource?.sourceBuffers.length) {\n          this.mediaSource.removeSourceBuffer(sb);\n        }\n      } catch (err) {\n        this.warn(`onBufferReset ${type}`, err);\n      }\n    }\n    delete this.tracks[type];\n  }\n\n  private removeBuffer(type: SourceBufferName) {\n    this.removeBufferListeners(type);\n    this.sourceBuffers[sourceBufferNameToIndex(type)] = [null, null];\n    const track = this.tracks[type];\n    if (track) {\n      this.clearBufferAppendTimeoutId(track);\n      track.buffer = undefined;\n    }\n  }\n\n  private resetQueue() {\n    if (this.operationQueue) {\n      this.operationQueue.destroy();\n    }\n    this.operationQueue = new BufferOperationQueue(this.tracks);\n  }\n\n  private onBufferCodecs(event: Events.BUFFER_CODECS, data: BufferCodecsData) {\n    const tracks = this.tracks;\n    const trackNames = Object.keys(data);\n    this.log(\n      `BUFFER_CODECS: \"${trackNames}\" (current SB count ${this.sourceBufferCount})`,\n    );\n    const unmuxedToMuxed =\n      ('audiovideo' in data && (tracks.audio || tracks.video)) ||\n      (tracks.audiovideo && ('audio' in data || 'video' in data));\n    const muxedToUnmuxed =\n      !unmuxedToMuxed &&\n      this.sourceBufferCount &&\n      this.media &&\n      trackNames.some((sbName) => !tracks[sbName]);\n    if (unmuxedToMuxed || muxedToUnmuxed) {\n      this.warn(\n        `Unsupported transition between \"${Object.keys(tracks)}\" and \"${trackNames}\" SourceBuffers`,\n      );\n      // Do not add incompatible track ('audiovideo' <-> 'video'/'audio').\n      // Allow following onBufferAppending handle to trigger BUFFER_APPEND_ERROR.\n      // This will either be resolved by level switch or could be handled with recoverMediaError().\n      return;\n    }\n    trackNames.forEach((trackName: SourceBufferName) => {\n      const parsedTrack = data[trackName] as ParsedTrack;\n      const { id, codec, levelCodec, container, metadata, supplemental } =\n        parsedTrack;\n      let track = tracks[trackName];\n      const transferredTrack = this.transferData?.tracks?.[trackName];\n      const sbTrack = transferredTrack?.buffer ? transferredTrack : track;\n      const sbCodec = sbTrack?.pendingCodec || sbTrack?.codec;\n      const trackLevelCodec = sbTrack?.levelCodec;\n      if (!track) {\n        track = tracks[trackName] = {\n          buffer: undefined,\n          listeners: [],\n          codec,\n          supplemental,\n          container,\n          levelCodec,\n          metadata,\n          id,\n        };\n      }\n      // check if SourceBuffer codec needs to change\n      const currentCodecFull = pickMostCompleteCodecName(\n        sbCodec,\n        trackLevelCodec,\n      );\n      const currentCodec = currentCodecFull?.replace(\n        VIDEO_CODEC_PROFILE_REPLACE,\n        '$1',\n      );\n      let trackCodec = pickMostCompleteCodecName(codec, levelCodec);\n      const nextCodec = trackCodec?.replace(VIDEO_CODEC_PROFILE_REPLACE, '$1');\n      if (trackCodec && currentCodecFull && currentCodec !== nextCodec) {\n        if (trackName.slice(0, 5) === 'audio') {\n          trackCodec = getCodecCompatibleName(trackCodec, this.appendSource);\n        }\n        this.log(`switching codec ${sbCodec} to ${trackCodec}`);\n        if (trackCodec !== (track.pendingCodec || track.codec)) {\n          track.pendingCodec = trackCodec;\n        }\n        track.container = container;\n        this.appendChangeType(trackName, container, trackCodec);\n      }\n    });\n\n    if (this.tracksReady || this.sourceBufferCount) {\n      data.tracks = this.sourceBufferTracks;\n    }\n\n    // if sourcebuffers already created, do nothing ...\n    if (this.sourceBufferCount) {\n      return;\n    }\n\n    if (\n      this.bufferCodecEventsTotal > 1 &&\n      !this.tracks.video &&\n      !data.video &&\n      data.audio?.id === 'main'\n    ) {\n      // MVP is missing CODECS and only audio was found in main segment (#7524)\n      this.log(`Main audio-only`);\n      this.bufferCodecEventsTotal = 1;\n    }\n\n    if (this.mediaSourceOpenOrEnded) {\n      this.checkPendingTracks();\n    }\n  }\n\n  public get sourceBufferTracks(): BaseTrackSet {\n    return Object.keys(this.tracks).reduce((baseTracks: BaseTrackSet, type) => {\n      const track = this.tracks[type] as SourceBufferTrack;\n      baseTracks[type] = {\n        id: track.id,\n        container: track.container,\n        codec: track.codec,\n        levelCodec: track.levelCodec,\n      };\n      return baseTracks;\n    }, {});\n  }\n\n  private appendChangeType(\n    type: SourceBufferName,\n    container: string,\n    codec: string,\n  ) {\n    const mimeType = `${container};codecs=${codec}`;\n    const operation: BufferOperation = {\n      label: `change-type=${mimeType}`,\n      execute: () => {\n        const track = this.tracks[type];\n        if (track) {\n          const sb = track.buffer;\n          if (sb?.changeType) {\n            this.log(`changing ${type} sourceBuffer type to ${mimeType}`);\n            sb.changeType(mimeType);\n            track.codec = codec;\n            track.container = container;\n          }\n        }\n        this.shiftAndExecuteNext(type);\n      },\n      onStart: () => {},\n      onComplete: () => {},\n      onError: (error: Error) => {\n        this.warn(`Failed to change ${type} SourceBuffer type`, error);\n      },\n    };\n    this.append(operation, type, this.isPending(this.tracks[type]));\n  }\n\n  private blockAudio(partOrFrag: MediaFragment | Part) {\n    const pStart = partOrFrag.start;\n    const pTime = pStart + partOrFrag.duration * 0.05;\n    const atGap =\n      this.fragmentTracker.getAppendedFrag(pStart, PlaylistLevelType.MAIN)\n        ?.gap === true;\n    if (atGap) {\n      return;\n    }\n    const op: BufferOperation = {\n      label: 'block-audio',\n      execute: () => {\n        const videoEnd = this.lastVideoAppendEnd;\n        if (\n          videoEnd > pTime ||\n          BufferHelper.isBuffered(this.tracks.video?.buffer, pTime) ||\n          this.fragmentTracker.getAppendedFrag(pTime, PlaylistLevelType.MAIN)\n            ?.gap === true\n        ) {\n          this.unblockAudio();\n        }\n      },\n      onStart: () => {},\n      onComplete: () => {},\n      onError: (error) => {\n        this.warn('Error executing block-audio operation', error);\n      },\n    };\n    this.append(op, 'audio', true);\n  }\n\n  private unblockAudio() {\n    if (this.operationQueue) {\n      this.operationQueue.unblockAudio();\n    }\n  }\n\n  private onBufferAppending(\n    event: Events.BUFFER_APPENDING,\n    eventData: BufferAppendingData,\n  ) {\n    const { tracks } = this;\n    const { data, type, parent, frag, part, chunkMeta, offset } = eventData;\n    const chunkStats = chunkMeta.buffering[type];\n    const trackProgress =\n      isMediaFragment