    return;\n    }\n\n    if (!this.sourceBufferCount) {\n      return;\n    }\n\n    const config: Readonly<HlsConfig> = hls.config;\n    const currentTime = media.currentTime;\n    const targetDuration = details.levelTargetDuration;\n\n    // Support for deprecated liveBackBufferLength\n    backBufferLength =\n      details.live && config.liveBackBufferLength !== null\n        ? config.liveBackBufferLength\n        : backBufferLength;\n\n    let targetBackBufferPosition = -Infinity;\n    if (Number.isFinite(backBufferLength) && backBufferLength >= 0) {\n      const maxBackBufferLength = Math.max(backBufferLength, targetDuration);\n      targetBackBufferPosition =\n        Math.floor(currentTime / targetDuration) * targetDuration -\n        maxBackBufferLength;\n    }\n\n    // For looped media with a quality upgrade, extend the flush position\n    // to remove lower-quality segments from the back buffer.\n    if (frag) {\n      const loopFlushEnd = this.getLoopBackBufferFlushEnd(\n        frag,\n        previousFrag ?? null,\n      );\n      if (loopFlushEnd > 0) {\n        targetBackBufferPosition = Math.max(\n          targetBackBufferPosition,\n          loopFlushEnd,\n        );\n      }\n    }\n\n    if (targetBackBufferPosition > 0) {\n      this.flushBackBuffer(\n        currentTime,\n        targetDuration,\n        targetBackBufferPosition,\n      );\n    }\n\n    if (\n      Number.isFinite(frontBufferFlushThreshold) &&\n      frontBufferFlushThreshold > 0\n    ) {\n      const frontBufferLength = Math.max(\n        config.maxBufferLength,\n        frontBufferFlushThreshold,\n      );\n\n      const maxFrontBufferLength = Math.max(frontBufferLength, targetDuration);\n      const targetFrontBufferPosition =\n        Math.floor(currentTime / targetDuration) * targetDuration +\n        maxFrontBufferLength;\n\n      this.flushFrontBuffer(\n        currentTime,\n        targetDuration,\n        targetFrontBufferPosition,\n      );\n    }\n  }\n\n  /**\n   * For looped media, determine the back buffer flush position to remove\n   * lower-quality segments on a quality upgrade. Returns 0 if no flush is needed.\n   */\n  private getLoopBackBufferFlushEnd(\n    frag: MediaFragment,\n    previousFrag: MediaFragment | null,\n  ): number {\n    const { media } = this;\n    if (\n      this.hls?.config.loopBackBufferFlush === false ||\n      !media?.loop ||\n      !previousFrag ||\n      frag.level <= previousFrag.level\n    ) {\n      return 0;\n    }\n\n    const { video, audiovideo } = frag.elementaryStreams;\n    if (video?.partial || audiovideo?.partial) {\n      return 0;\n    }\n\n    const flushEnd =\n      this.getEarliestElementaryStreamStart(frag) - LOOP_FLUSH_SAFETY_MARGIN;\n    if (flushEnd <= 0) {\n      return 0;\n    }\n\n    this.log(\n      `Flushing lower quality back buffer for loop: level ${frag.level}, range [0-${flushEnd.toFixed(3)}]`,\n    );\n    return flushEnd;\n  }\n\n  private getEarliestElementaryStreamStart(frag: MediaFragment): number {\n    const { audio, video, audiovideo } = frag.elementaryStreams;\n    let earliest = frag.start;\n    if (audiovideo) {\n      earliest = Math.min(earliest, audiovideo.startDTS);\n    } else {\n      if (audio) {\n        earliest = Math.min(earliest, audio.startDTS);\n      }\n      if (video) {\n        earliest = Math.min(earliest, video.startDTS);\n      }\n    }\n    return earliest;\n  }\n\n  private flushBackBuffer(\n    currentTime: number,\n    targetDuration: number,\n    targetBackBufferPosition: number,\n  ) {\n    this.sourceBuffers.forEach(([type, sb]) => {\n      if (sb) {\n        const buffered = BufferHelper.getBuffered(sb);\n        // when target buffer start exceeds actual buffer start\n        if (\n          buffered.length > 0 &&\n          targetBackBufferPosition > buffered.start(0)\n        ) {\n          this.hls.trigger(Events.BACK_BUFFER_REACHED, {\n            bufferEnd: targetBackBufferPosition,\n          });\n\n          // Support for deprecated event:\n          const track = this.tracks[type];\n          if (this.details?.live) {\n            this.hls.trigger(Events.LIVE_BACK_BUFFER_REACHED, {\n              bufferEnd: targetBackBufferPosition,\n            });\n          } else if (\n            track?.ended &&\n            !(\n              this.media?.loop && this.hls?.config.loopBackBufferFlush !== false\n            )\n          ) {\n            this.log(\n              `Cannot flush ${type} back buffer while SourceBuffer is in ended state`,\n            );\n            return;\n          }\n\n          this.hls.trigger(Events.BUFFER_FLUSHING, {\n            startOffset: 0,\n            endOffset: targetBackBufferPosition,\n            type,\n          });\n        }\n      }\n    });\n  }\n\n  private flushFrontBuffer(\n    currentTime: number,\n    targetDuration: number,\n    targetFrontBufferPosition: number,\n  ) {\n    this.sourceBuffers.forEach(([type, sb]) => {\n      if (sb) {\n        const buffered = BufferHelper.getBuffered(sb);\n        const numBufferedRanges = buffered.length;\n        // The buffer is either empty or contiguous\n        if (numBufferedRanges < 2) {\n          return;\n        }\n        const bufferStart = buffered.start(numBufferedRanges - 1);\n        const bufferEnd = buffered.end(numBufferedRanges - 1);\n        // No flush if we can tolerate the current buffer length or the current buffer range we would flush is contiguous with current position\n        if (\n          targetFrontBufferPosition > bufferStart ||\n          (currentTime >= bufferStart && currentTime <= bufferEnd)\n        ) {\n          return;\n        }\n\n        this.hls.trigger(Events.BUFFER_FLUSHING, {\n          startOffset: bufferStart,\n          endOffset: Infinity,\n          type,\n        });\n      }\n    });\n  }\n\n  /**\n   * Update Media Source duration to current level duration or override to Infinity if configuration parameter\n   * 'liveDurationInfinity` is set to `true`\n   * More details: https://github.com/video-dev/hls.js/issues/355\n   */\n  private getDurationAndRange(): {\n    duration: number;\n    start?: number;\n    end?: number;\n  } | null {\n    const { details, mediaSource } = this;\n    if (!details || !this.media || mediaSource?.readyState !== 'open') {\n      return null;\n    }\n    const playlistEnd = details.edge;\n    if (details.live && this.hls.config.liveDurationInfinity) {\n      const len = details.fragments.length;\n      if (len && !!(mediaSource as any).setLiveSeekableRange) {\n        const start = Math.max(0, details.fragmentStart);\n        const end = Math.max(start, playlistEnd);\n\n        return { duration: Infinity, start, end };\n      }\n      return { duration: Infinity };\n    }\n    const overrideDuration = this.overrides?.duration;\n    if (overrideDuration) {\n      if (!Number.isFinite(overrideDuration)) {\n        return null;\n      }\n      return { duration: overrideDuration };\n    }\n    const mediaDuration = this.media.duration;\n    const msDuration = Number.isFinite(mediaSource.duration)\n      ? mediaSource.duration\n      : 0;\n    if (\n      (playlistEnd > msDuration && playlistEnd > mediaDuration) ||\n      !Number.isFinite(mediaDuration)\n    ) {\n      return { duration: playlistEnd };\n    }\n    return null;\n  }\n\n  private updateMediaSource({\n    duration,\n    start,\n    end,\n  }: {\n    duration: number;\n    start?: number;\n    end?: number;\n  }) {\n    const mediaSource = this.mediaSource;\n    if (!mediaSource || !this.media || mediaSource.readyState !== 'open') {\n      return;\n    }\n    if (mediaSource.duration !== duration) {\n      if (Number.isFinite(duration)) {\n        this.log(`Updating MediaSource duration to ${duration.toFixed(3)}`);\n      }\n      mediaSource.duration = duration;\n    }\n    if (start !== undefined && end !== undefined) {\n      this.log(\n        `MediaSource duration is set to ${mediaSource.duration}. Setting seekable range to ${start}-${end}.`,\n      );\n      mediaSource.setLiveSeekableRange(start, end);\n    }\n  }\n\n  private get tracksReady(): boolean {\n    const pendingTrackCount = this.pendingTrackCount;\n    return (\n      pendingTrackCount > 0 &&\n      (pendingTrackCount >= this.bufferCodecEventsTotal ||\n        this.isPending(this.tracks.audiovideo))\n    );\n  }\n\n  private checkPendingTracks() {\n    const { bufferCodecEventsTotal, pendingTrackCount, tracks } = this;\n    this.log(\n      `checkPendingTracks (pending: ${pendingTrackCount} codec events expected: ${bufferCodecEventsTotal}) ${stringify(tracks)}`,\n    );\n    // Check if we've received all of the expected bufferCodec events. When none remain, create all the sourceBuffers at once.\n    // This is important because the MSE spec allows implementations to throw QuotaExceededErrors if creating new sourceBuffers after\n    // data has been appended to existing ones.\n    // 2 tracks is the max (one for audio, one for video). If we've reach this max go ahead and create the buffers.\n    if (this.tracksReady) {\n      const transferredTracks = this.transferData?.tracks;\n      if (transferredTracks && Object.keys(transferredTracks).length) {\n        this.attachTransferred();\n      } else {\n        // ok, let's create them now !\n        this.createSourceBuffers();\n      }\n    }\n  }\n\n  private bufferCreated() {\n    if (this.sourceBufferCount) {\n      const tracks: BufferCreatedTrackSet = {};\n      this.sourceBuffers.forEach(([type, buffer]) => {\n        if (type) {\n          const track = this.tracks[type] as SourceBufferTrack;\n          tracks[type] = {\n            buffer,\n            container: track.container,\n            codec: track.codec,\n            supplemental: track.supplemental,\n            levelCodec: track.levelCodec,\n            id: track.id,\n            metadata: track.metadata,\n          };\n        }\n      });\n      this.hls.trigger(Events.BUFFER_CREATED, {\n        tracks,\n      });\n      this.log(`SourceBuffers created. Running queue: ${this.operationQueue}`);\n      this.sourceBuffers.forEach(([type]) => {\n        this.executeNext(type);\n      });\n    } else {\n      const error = new Error(\n        'could not create source buffer for media codec(s)',\n      );\n      this.hls.trigger(Events.ERROR, {\n        type: ErrorTypes.MEDIA_ERROR,\n        details: ErrorDetails.BUFFER_INCOMPATIBLE_CODECS_ERROR,\n        fatal: true,\n        error,\n        reason: error.message,\n      });\n    }\n  }\n\n  private createSourceBuffers() {\n    const { tracks, sourceBuffers, mediaSource } = this;\n    if (!mediaSource) {\n      throw new Error('createSourceBuffers called when mediaSource was null');\n    }\n\n    for (const trackName in tracks) {\n      const type = trackName as SourceBufferName;\n      const track = tracks[type];\n      if (this.isPending(track)) {\n        const codec = this.getTrackCodec(track, type);\n        const mimeType = `${track.container};codecs=${codec}`;\n        track.codec = codec;\n        this.log(\n          `creating sourceBuffer(${mimeType})${this.currentOp(type) ? ' Queued' : ''} ${stringify(track)}`,\n        );\n        try {\n          const sb = mediaSource.addSourceBuffer(\n            mimeType,\n          ) as ExtendedSourceBuffer;\n          const sbIndex = sourceBufferNameToIndex(type);\n          const sbTuple = [type, sb] as Exclude<\n            SourceBuffersTuple[typeof sbIndex],\n            EmptyTuple\n          >;\n          sourceBuffers[sbIndex] = sbTuple as any;\n          track.buffer = sb;\n        } catch (error) {\n          this.error(\n            `error while trying to add sourceBuffer: ${error.message}`,\n          );\n          // remove init segment from queue and delete track info\n          this.shiftAndExecuteNext(type);\n          this.operationQueue?.removeBlockers();\n          delete this.tracks[type];\n          this.hls.trigger(Events.ERROR, {\n            type: ErrorTypes.MEDIA_ERROR,\n            details: ErrorDetails.BUFFER_ADD_CODEC_ERROR,\n            fatal: false,\n            error,\n            sourceBufferName: type,\n            mimeType: mimeType,\n            parent: track.id as PlaylistLevelType,\n          });\n          return;\n        }\n        this.trackSourceBuffer(type, track);\n      }\n    }\n    this.bufferCreated();\n  }\n\n  private clearBufferAppendTimeoutId(track?: SourceBufferTrack): void {\n    if (!track) {\n      return;\n    }\n\n    self.clearTimeout(track.bufferAppendTimeoutId);\n    track.bufferAppendTimeoutId = undefined;\n  }\n\n  private getTrackCodec(track: BaseTrack, trackName: SourceBufferName): string {\n    // Use supplemental video codec when supported when adding SourceBuffer (#5558)\n    const supplementalCodec = track.supplemental;\n    let trackCodec = track.codec;\n    if (\n      supplementalCodec &&\n      (trackName === 'video' || trackName === 'audiovideo') &&\n      areCodecsMediaSourceSupported(supplementalCodec, 'video')\n    ) {\n      trackCodec = replaceVideoCodec(trackCodec, supplementalCodec);\n    }\n    const codec = pickMostCompleteCodecName(trackCodec, track.levelCodec);\n    if (codec) {\n      if (trackName.slice(0, 5) === 'audio') {\n        return getCodecCompatibleName(codec, this.appendSource);\n      }\n      return codec;\n    }\n    return '';\n  }\n\n  private trackSourceBuffer(type: SourceBufferName, track: SourceBufferTrack) {\n    const buffer = track.buffer;\n    if (!buffer) {\n      return;\n    }\n    const codec = this.getTrackCodec(track, type);\n    this.tracks[type] = {\n      buffer,\n      codec,\n      container: track.container,\n      levelCodec: track.levelCodec,\n      supplemental: track.supplemental,\n      metadata: track.metadata,\n      id: track.id,\n      listeners: [],\n    };\n    this.removeBufferListeners(type);\n    this.addBufferListener(type, 'updatestart', this.onSBUpdateStart);\n    this.addBufferListener(type, 'updateend', this.onSBUpdateEnd);\n    this.addBufferListener(type, 'error', this.onSBUpdateError);\n    // ManagedSourceBuffer bufferedchange event\n    if (this.appendSource) {\n      this.addBufferListener(\n        type,\n        'bufferedchange',\n        (type: SourceBufferName, event: BufferedChangeEvent) => {\n          // If media was ejected check for a change. Added ranges are redundant with changes on 'updateend' event.\n          const removedRanges = event.removedRanges;\n          if (removedRanges?.length) {\n            this.log(\n              `${type} buffer removed ${timeRangesToString(removedRanges)}`,\n            );\n            this.hls.trigger(Events.BUFFER_FLUSHED, {\n              type: type,\n              start: removedRanges.start(0),\n              end: removedRanges.end(removedRanges.length - 1),\n            });\n          }\n        },\n      );\n    }\n  }\n\n  // Keep as arrow functions so that we can directly reference these functions directly as event listeners\n  private _onMediaSourceOpen = (e?: Event) => {\n    const { media, mediaSource } = this;\n    if (e) {\n      this.log('Media source opened');\n    }\n    if (!media || !mediaSource) {\n      return;\n    }\n    // once received, don't listen anymore to sourceopen event\n    removeEventListener(mediaSource, 'sourceopen', this._onMediaSourceOpen);\n    removeEventListener(media, 'emptied', this._onMediaEmptied);\n    this.updateDuration();\n    this.hls.trigger(Events.MEDIA_ATTACHED, {\n      media,\n      mediaSource: mediaSource as MediaSource,\n    });\n\n    if (this.mediaSource !== null) {\n      this.checkPendingTracks();\n    }\n  };\n\n  private _onMediaSourceClose = () => {\n    this.log('Media source closed');\n    // Safari/WebKit bug: MediaSource becomes invalid after bfcache restoration.\n    // When the user navigates back, the MediaSource is in a 'closed' state and cannot be used.\n    // If sourceclose fires while media is still attached, trigger recovery to reattach media.\n    if (this.media) {\n      const mediaError = this.media.error;\n      const { appendError, appendErrors } = this;\n      let fatal = false;\n      if (!appendError && mediaError) {\n        // decode error with no append error\n        const appendErrorCount = Math.max(\n          ++appendErrors.audio,\n          ++appendErrors.video,\n          ++appendErrors.audiovideo,\n        );\n        fatal = appendErrorCount >= this.hls.config.appendErrorMaxRetry;\n      }\n      const error = new Error(\n        `MediaSource closed while media attached${mediaErrorRecoveryMessage(fatal, mediaError)}`,\n      );\n      this.warn(error);\n      this.hls.trigger(\n        Events.ERROR,\n        Object.assign({ fatal }, appendError, {\n          type: ErrorTypes.MEDIA_ERROR,\n          details: ErrorDetails.MEDIA_SOURCE_REQUIRES_RESET,\n          error,\n        }),\n      );\n    }\n  };\n\n  private _onMediaSourceEnded = () => {\n    this.log('Media source ended');\n  };\n\n  private _onMediaEmptied = () => {\n    const { mediaSrc, _objectUrl } = this;\n    if (mediaSrc !== _objectUrl) {\n      this.error(\n        `Media element src was set while attaching MediaSource (${_objectUrl} > ${mediaSrc})`,\n      );\n    }\n  };\n\n  private _onMediaError = () => {\n    const { media } = this;\n    if (media) {\n      this.log(\n        `Media error (code: ${media.error?.code}): ${media.error?.message}`,\n      );\n    }\n  };\n\n  private get mediaSrc(): string | undefined {\n    const media = (this.media?.querySelector as any)?.('source') || this.media;\n    return media?.src;\n  }\n\n  private onSBUpdateStart(type: SourceBufferName) {\n    const operation = this.currentOp(type);\n    if (!operation) {\n      return;\n    }\n    operation.onStart();\n  }\n\n  private onSBUpdateEnd(type: SourceBufferName) {\n    if (this.mediaSource?.readyState === 'closed') {\n      this.resetBuffer(type);\n      return;\n    }\n    const operation = this.currentOp(type);\n    if (!operation) {\n      return;\n    }\n    operation.onComplete();\n\n    const updating = this.tracks[type]?.buffer?.updating;\n    if (updating) {\n      this.log(`${type} SourceBuffer updating on \"updateend\"`);\n      this.blockUntilOpen(() => {\n        this.shiftAndExecuteNext(type);\n      });\n      return;\n    }\n    this.shiftAndExecuteNext(type);\n  }\n\n  private onSBUpdateError(type: SourceBufferName, event: Event) {\n    const readyState = this.mediaSource?.readyState;\n    const error = new Error(\n      `${type} SourceBuffer error. MediaSource readyState: ${readyState}`,\n    );\n    this.error(`${error.message}`, event);\n    // according to http://www.w3.org/TR/media-source/#sourcebuffer-append-error\n    // SourceBuffer errors are not necessarily fatal; if so, the HTMLMediaElement will fire an error event\n    this.hls.trigger(Events.ERROR, {\n      type: ErrorTypes.MEDIA_ERROR,\n      details: ErrorDetails.BUFFER_APPENDING_ERROR,\n      sourceBufferName: type,\n      error,\n      fatal: false,\n    });\n    // updateend is always fired after error, so we'll allow that to shift the current operation off of the queue\n    const operation = this.currentOp(type);\n    if (operation) {\n      operation.onError(error);\n    }\n  }\n\n  private updateTimestampOffset(\n    sb: ExtendedSourceBuffer,\n    timestampOffset: number,\n    tolerance: number,\n    type: SourceBufferName,\n    sn: number | 'initSegment',\n    cc: number,\n  ) {\n    const delta = timestampOffset - sb.timestampOffset;\n    if (Math.abs(delta) >= tolerance) {\n      this.log(\n        `Updating ${type} SourceBuffer timestampOffset to ${timestampOffset} (sn: ${sn} cc: ${cc})`,\n      );\n      sb.timestampOffset = timestampOffset;\n    }\n  }\n\n  // This method must result in an updateend event; if remove is not called, onSBUpdateEnd must be called manually\n  private removeExecutor(\n    type: SourceBufferName,\n    startOffset: number,\n    endOffset: number,\n  ) {\n    const { media, mediaSource } = this;\n    const track = this.tracks[type];\n    const sb = track?.buffer;\n    if (!media || !mediaSource || !sb) {\n      throw new Error(\n        `Attempting to remove from the ${type} SourceBuffer, but it does not exist`,\n      );\n    }\n    const mediaDuration = Number.isFinite(media.duration)\n      ? media.duration\n      : Infinity;\n    const msDuration = Number.isFinite(mediaSource.duration)\n      ? mediaSource.duration\n      : Infinity;\n    const removeStart = Math.max(0, startOffset);\n    if (removeStart >= msDuration) {\n      this.currentOp(type)?.onComplete();\n      this.shiftAndExecuteNext(type);\n      return;\n    }\n    const removeEnd = Math.min(endOffset, mediaDuration, msDuration);\n    if (removeEnd > removeStart && (!track.ending || track.ended)) {\n      track.ended = false;\n      this.log(\n        `Removing [${removeStart},${removeEnd}] from the ${type} SourceBuffer`,\n      );\n      sb.remove(removeStart, removeEnd);\n    } else {\n      throw new Error(\n        `Cannot remove ${removeEnd <= removeStart ? `invalid range (${removeStart} >= ${removeEnd}) ` : ''}from the ${type} SourceBuffer${track.ending ? ' while track ending' : ''}`,\n      );\n    }\n  }\n\n  // This method must result in an updateend event; if append is not called, onSBUpdateEnd must be called manually\n  private appendExecutor(\n    data: Uint8Array<ArrayBuffer>,\n    type: SourceBufferName,\n  ) {\n    const track = this.tracks[type];\n    const sb = track?.buffer;\n    if (!sb) {\n      throw new HlsJsTrackRemovedError(\n        `Attempting to append to the ${type} SourceBuffer, but it does not exist`,\n      );\n    }\n    track.ending = false;\n    track.ended = false;\n\n    if (this.hls.config.appendTimeout !== Infinity) {\n      const appendTimeoutTime = this.calculateAppendTimeoutTime(sb);\n\n      track.bufferAppendTimeoutId = self.setTimeout(\n        () => this.appendTimeoutHandler(type, sb, appendTimeoutTime),\n        appendTimeoutTime,\n      );\n    }\n\n    sb.appendBuffer(data);\n  }\n\n  private appendTimeoutHandler(\n    type: SourceBufferName,\n    sb: ExtendedSourceBuffer,\n    appendTimeoutTime: number,\n  ) {\n    this.log(\n      `Received timeout after ${appendTimeoutTime}ms for append on ${type} source buffer. Aborting and triggering error.`,\n    );\n\n    try {\n      sb.abort();\n    } catch (e) {\n      this.log(\n        `Failed to abort append on ${type} source buffer after timeout.`,\n      );\n    }\n\n    const operation = this.currentOp(type);\n    if (operation) {\n      operation.onError(new Error(`${type}-append-timeout`));\n    }\n  }\n\n  private calculateAppendTimeoutTime(sb: ExtendedSourceBuffer): number {\n    let targetDuration = DEFAULT_TARGET_DURATION;\n\n    if (this.details) {\n      targetDuration = this.details.levelTargetDuration;\n    }\n\n    // 2 Target durations\n    let desiredDefaultTimeoutValue = 2 * targetDuration * 1000;\n\n    if (this.media === null) {\n      return desiredDefaultTimeoutValue;\n    }\n\n    const activeBufferedRange = BufferHelper.bufferInfo(\n      sb,\n      this.media.currentTime,\n      0,\n    );\n\n    if (!activeBufferedRange.len) {\n      return desiredDefaultTimeoutValue;\n    }\n\n    desiredDefaultTimeoutValue = Math.max(\n      activeBufferedRange.len * 1000,\n      desiredDefaultTimeoutValue,\n    );\n\n    return Math.max(this.hls.config.appendTimeout, desiredDefaultTimeoutValue);\n  }\n\n  private blockUntilOpen(callback: () => void) {\n    if (this.isUpdating() || this.isQueued()) {\n      this.blockBuffers(callback).catch((error) => {\n        this.warn(`SourceBuffer blocked callback ${error}`);\n        this.stepOperationQueue(this.sourceBufferTypes);\n      });\n    } else {\n      try {\n        callback();\n      } catch (error) {\n        this.warn(\n          `Callback run without blocking ${this.operationQueue} ${error}`,\n        );\n      }\n    }\n  }\n\n  private isUpdating(): boolean {\n    return this.sourceBuffers.some(([type, sb]) => type && sb.updating);\n  }\n\n  private isQueued(): boolean {\n    return this.sourceBuffers.some(([type]) => type && !!this.currentOp(type));\n  }\n\n  private isPending(\n    track: SourceBufferTrack | undefined,\n  ): track is SourceBufferTrack {\n    return !!track && !track.buffer;\n  }\n\n  private isAudioBlocked(): boolean {\n    return this.currentOp('audio')?.label === 'block-audio';\n  }\n\n  private isAudioBlocking(): boolean {\n    if (this.operationQueue) {\n      return this.operationQueue.audioBlocking();\n    }\n    return false;\n  }\n\n  // Enqueues an operation to each SourceBuffer queue which, upon execution, resolves a promise. When all promises\n  // resolve, the onUnblocked function is executed. Functions calling this method do not need to unblock the queue\n  // upon completion, since we already do it here\n  private blockBuffers(\n    onUnblocked: () => void,\n    bufferNames: SourceBufferName[] = this.sourceBufferTypes,\n  ): Promise<void> {\n    if (!bufferNames.length) {\n      this.log('Blocking operation requested, but no SourceBuffers exist');\n      return Promise.resolve().then(onUnblocked);\n    }\n    const { operationQueue } = this;\n\n    const audioAlreadyBlocked =\n      bufferNames.length === 2 && this.isAudioBlocking();\n    // logger.debug(`[buffer-controller]: Blocking ${buffers} SourceBuffer`);\n    const blockingOperations = audioAlreadyBlocked\n      ? [this.appendBlocker('video')]\n      : bufferNames.map((type) => this.appendBlocker(type));\n    return Promise.all(blockingOperations).then((result) => {\n      if (operationQueue !== this.operationQueue) {\n        return;\n      }\n      // logger.debug(`[buffer-controller]: Blocking operation resolved; unblocking ${buffers} SourceBuffer`);\n      onUnblocked();\n      this.stepOperationQueue(this.sourceBufferTypes);\n    });\n  }\n\n  private stepOperationQueue(bufferNames: SourceBufferName[]) {\n    bufferNames.forEach((type) => {\n      const sb = this.tracks[type]?.buffer;\n      // Only cycle the queue if the SB is not updating. There's a bug in Chrome which sets the SB updating flag to\n      // true when changing the MediaSource duration (https://bugs.chromium.org/p/chromium/issues/detail?id=959359&can=2&q=mediasource%20duration)\n      // While this is a workaround, it's probably useful to have around\n      if (!sb || sb.updating || (type === 'audio' && this.isAudioBlocked())) {\n        return;\n      }\n      this.shiftAndExecuteNext(type);\n    });\n  }\n\n  private append(\n    operation: BufferOperation,\n    type: SourceBufferName,\n    pending?: boolean,\n  ) {\n    if (this.operationQueue) {\n      this.operationQueue.append(operation, type, pending);\n    }\n  }\n\n  private insertNext(operations: BufferOperation[], type: SourceBufferName) {\n    if (this.operationQueue) {\n      this.operationQueue.insertNext(operations, type);\n    }\n  }\n\n  private appendBlocker(type: SourceBufferName): Promise<void> | undefined {\n    if (this.operationQueue) {\n      return this.operationQueue.appendBlocker(type);\n    }\n  }\n\n  private currentOp(type: SourceBufferName): BufferOperation | null {\n    if (this.operationQueue) {\n      return this.operationQueue.current(type);\n    }\n    return null;\n  }\n\n  private executeNext(type: SourceBufferName | null) {\n    if (type && this.operationQueue) {\n      this.operationQueue.executeNext(type);\n    }\n  }\n\n  private shiftAndExecuteNext(type: SourceBufferName) {\n    if (this.operationQueue) {\n      this.operationQueue.shiftAndExecuteNext(type);\n    }\n  }\n\n  private get pendingTrackCount(): number {\n    return Object.keys(this.tracks).reduce(\n      (acc, type) =>\n        acc + (this.isPending(this.tracks[type as SourceBufferName]) ? 1 : 0),\n      0,\n    );\n  }\n\n  private get sourceBufferCount(): number {\n    return this.sourceBuffers.reduce((acc, [type]) => acc + (type ? 1 : 0), 0);\n  }\n\n  private get sourceBufferTypes(): SourceBufferName[] {\n    return this.sourceBuffers\n      .map(([type]) => type)\n      .filter((type) => !!type) as SourceBufferName[];\n  }\n\n  private addBufferListener(\n    type: SourceBufferName,\n    event: string,\n    fn: <K extends keyof SourceBufferEventMap>(\n      type: SourceBufferName,\n      event: SourceBufferEventMap[K],\n    ) => any,\n  ) {\n    const track = this.tracks[type];\n    if (!track) {\n      return;\n    }\n    const buffer = track.buffer;\n    if (!buffer) {\n      return;\n    }\n    const listener = fn.bind(this, type);\n    track.listeners.push({ event, listener });\n    addEventListener(buffer, event, listener);\n  }\n\n  private removeBufferListeners(type: SourceBufferName) {\n    const track = this.tracks[type];\n    if (!track) {\n      return;\n    }\n    const buffer = track.buffer;\n    if (!buffer) {\n      return;\n    }\n    track.listeners.forEach((l) => {\n      removeEventListener(buffer, l.event, l.listener);\n    });\n    track.listeners.length = 0;\n  }\n}\n\nfunction removeSourceChildren(node: HTMLElement) {\n  const sourceChildren = node.querySelectorAll('source');\n  [].slice.call(sourceChildren).forEach((source) => {\n    node.removeChild(source);\n  });\n}\n\nfunction addSource(media: HTMLMediaElement, url: string) {\n  const source = self.document.createElement('source');\n  source.type = 'video/mp4';\n  source.src = url;\n  media.appendChild(source);\n}\n\nfunction sourceBufferNameToIndex(type: SourceBufferName) {\n  return type === 'audio' ? 1 : 0;\n}\n\nfunction mediaErrorRecoveryMessage(\n  fatal: boolean,\n  mediaError: MediaError | null | undefined,\n) {\n  return `${fatal ? '' : ' - triggering recovery'}${mediaError ? ' with HTMLMediaElement Error: ' + mediaError.message : ''}`;\n}\n\nfunction appendProgressKey(fragment: MediaFragment): string {\n  return `${fragment.type}_${fragment.sn}_${fragment.level}`;\n}\n\n// Buffered time within the fragment's interval\nfunction fragmentBufferedCoverage(\n  timeRanges: BufferTimeRange[],\n  fragment: Fragment,\n): number {\n  const { start, end } = fragment;\n  let coverage = 0;\n  for (let i = 0; i < timeRanges.length; i++) {\n    const timeRange = timeRanges[i];\n    if (timeRange.start >= end) {\n      break;\n    }\n    const rangeStart = Math.max(start, timeRange.start);\n    const rangeEnd = Math.min(end, timeRange.end);\n    if (rangeEnd > rangeStart) {\n      coverage += rangeEnd - rangeStart;\n    }\n  }\n  return coverage;\n}\n\nfunction isFragmentFullyBuffered(\n  coverage: number,\n  fragment: Fragment,\n): boolean {\n  // .05 BUFFER_APPEND_NO_PROGRESS coverage tolerance accounts for large composition times\n  return fragment.duration - coverage <= 0.05;\n}\n","/*\n * cap stream level to media size dimension controller\n */\n\nimport { Events } from '../events';\nimport type StreamController from './stream-controller';\nimport type Hls from '../hls';\nimport type { ComponentAPI } from '../types/component-api';\nimport type {\n  BufferCodecsData,\n  FPSDropLevelCappingData,\n  ManifestParsedData,\n  MediaAttachingData,\n} from '../types/events';\nimport type { Level } from '../types/level';\n\ntype RestrictedLevel = { width: number; height: number; bitrate: number };\nclass CapLevelController implements ComponentAPI {\n  private hls: Hls | null = null;\n  private autoLevelCapping: number;\n  private media: HTMLVideoElement | null;\n  private restrictedLevels: RestrictedLevel[];\n  private timer?: number;\n  private observer?: ResizeObserver;\n  private clientRect: { width: number; height: number } | null;\n  private streamController?: StreamController;\n\n  constructor(hls: Hls) {\n    this.hls = hls;\n    this.autoLevelCapping = Number.POSITIVE_INFINITY;\n    this.media = null;\n    this.restrictedLevels = [];\n    this.clientRect = null;\n\n    this.registerListeners();\n  }\n\n  public setStreamController(streamController: StreamController) {\n    this.streamController = streamController;\n  }\n\n  public destroy() {\n    if (this.hls) {\n      this.unregisterListener();\n    }\n    if (this.timer || this.observer) {\n      this.stopCapping();\n    }\n    this.media = this.clientRect = this.hls = null;\n    // @ts-ignore\n    this.streamController = undefined;\n  }\n\n  protected registerListeners() {\n    const { hls } = this;\n    if (hls) {\n      hls.on(Events.FPS_DROP_LEVEL_CAPPING, this.onFpsDropLevelCapping, this);\n      hls.on(Events.MEDIA_ATTACHING, this.onMediaAttaching, this);\n      hls.on(Events.MANIFEST_PARSED, this.onManifestParsed, this);\n      hls.on(Events.LEVELS_UPDATED, this.onLevelsUpdated, this);\n      hls.on(Events.BUFFER_CODECS, this.onBufferCodecs, this);\n      hls.on(Events.MEDIA_DETACHING, this.onMediaDetaching, this);\n    }\n  }\n\n  protected unregisterListener() {\n    const { hls } = this;\n    if (hls) {\n      hls.off(Events.FPS_DROP_LEVEL_CAPPING, this.onFpsDropLevelCapping, this);\n      hls.off(Events.MEDIA_ATTACHING, this.onMediaAttaching, this);\n      hls.off(Events.MANIFEST_PARSED, this.onManifestParsed, this);\n      hls.off(Events.LEVELS_UPDATED, this.onLevelsUpdated, this);\n      hls.off(Events.BUFFER_CODECS, this.onBufferCodecs, this);\n      hls.off(Events.MEDIA_DETACHING, this.onMediaDetaching, this);\n    }\n  }\n\n  protected onFpsDropLevelCapping(\n    event: Events.FPS_DROP_LEVEL_CAPPING,\n    data: FPSDropLevelCappingData,\n  ) {\n    if (!this.hls) {\n      return;\n    }\n    // Don't add a restricted level more than once\n    const level = this.hls.levels[data.droppedLevel];\n    if (this.isLevelAllowed(level)) {\n      this.restrictedLevels.push({\n        bitrate: level.bitrate,\n        height: level.height,\n        width: level.width,\n      });\n    }\n  }\n\n  protected onMediaAttaching(\n    event: Events.MEDIA_ATTACHING,\n    data: MediaAttachingData,\n  ) {\n    const media = data.media;\n    this.clientRect = null;\n    if (!this.hls) {\n      return;\n    }\n    if (media instanceof HTMLVideoElement) {\n      this.media = media;\n      if (this.hls.config.capLevelToPlayerSize) {\n        this.observe();\n      }\n    } else {\n      this.media = null;\n    }\n    if ((this.timer || this.observer) && this.hls.levels.length > 1) {\n      this.detectPlayerSize();\n    }\n  }\n\n  protected onManifestParsed(\n    event: Events.MANIFEST_PARSED,\n    data: ManifestParsedData,\n  ) {\n    this.restrictedLevels = [];\n    if (data.video) {\n      // Start capping immediately if the manifest has signaled video codecs\n      this.startCapping();\n    }\n    this.onLevelsUpdated();\n  }\n\n  private onLevelsUpdated() {\n    if (!this.hls) {\n      return;\n    }\n    if (\n      (this.timer || this.observer) &&\n      (Number.isFinite(this.autoLevelCapping) || this.clientRect)\n    ) {\n      // Update capped level index when levels change (or stop observing if length is 1)\n      this.detectPlayerSize();\n    } else if (this.observer === undefined && this.timer === undefined) {\n      const levels = this.hls.levels;\n      // Restart observing if length increases\n      if (levels.length > 1 && levels.some((level) => !!level.videoCodec)) {\n        this.startCapping();\n      }\n    }\n  }\n\n  // Only activate capping when playing a video stream; otherwise, multi-bitrate audio-only streams will be restricted\n  // to the first level\n  protected onBufferCodecs(\n    event: Events.BUFFER_CODECS,\n    data: BufferCodecsData,\n  ) {\n    if (data.video) {\n      // If the manifest did not signal a video codec capping has been deferred until we're certain video is present\n      this.startCapping();\n    }\n  }\n\n  protected onMediaDetaching() {\n    this.stopCapping();\n    this.media = null;\n  }\n\n  detectPlayerSize() {\n    if (this.media) {\n      if (this.mediaHeight <= 0 || this.mediaWidth <= 0 || !this.hls) {\n        this.clientRect = null;\n        return;\n      }\n      const levels = this.hls.levels;\n      if (levels.length > 1) {\n        const hls = this.hls;\n        const maxLevel = this.getMaxLevel(levels.length - 1);\n        if (maxLevel !== this.autoLevelCapping) {\n          hls.logger.log(\n            `Setting autoLevelCapping to ${maxLevel}: ${levels[maxLevel].height}p@${levels[maxLevel].bitrate} for media ${this.mediaWidth}x${this.mediaHeight}`,\n          );\n        }\n        hls.autoLevelCapping = maxLevel;\n        if (\n          hls.autoLevelEnabled &&\n          hls.autoLevelCapping > this.autoLevelCapping &&\n          this.streamController\n        ) {\n          // if auto level capping has a higher value for the previous one, flush the buffer using nextLevelSwitch\n          // usually happen when the user go to the fullscreen mode.\n          this.streamController.nextLevelSwitch();\n        }\n        this.autoLevelCapping = hls.autoLevelCapping;\n      } else if (levels.length === 1) {\n        this.stopCapping();\n      }\n    }\n  }\n\n  /*\n   * returns level should be the one with the dimensions equal or greater than the media (player) dimensions (so the video will be downscaled)\n   */\n  getMaxLevel(capLevelIndex: number): number {\n    if (!this.hls) {\n      return -1;\n    }\n    const levels = this.hls.levels;\n    if (!levels.length) {\n      return -1;\n    }\n\n    const validLevels = levels.filter(\n      (level, index) => this.isLevelAllowed(level) && index <= capLevelIndex,\n    );\n    if (!this.observer) {\n      this.clientRect = null;\n    }\n    return CapLevelController.getMaxLevelByMediaSize(\n      validLevels,\n      this.mediaWidth,\n      this.mediaHeight,\n    );\n  }\n\n  private observe() {\n    const ResizeObserver = self.ResizeObserver;\n    if (ResizeObserver) {\n      this.observer = new ResizeObserver((entries) => {\n        const bounds = entries[0]?.contentRect;\n        if (bounds) {\n          this.clientRect = bounds;\n          this.detectPlayerSize();\n        }\n      });\n    }\n    if (this.observer && this.media) {\n      this.observer.observe(this.media);\n    }\n  }\n\n  startCapping() {\n    if (this.timer || this.observer || !this.hls?.config.capLevelToPlayerSize) {\n      // Don't reset capping if started twice; this can happen if the manifest signals a video codec\n      return;\n    }\n    self.clearInterval(this.timer);\n    this.timer = undefined;\n    this.autoLevelCapping = Number.POSITIVE_INFINITY;\n    this.observe();\n    if (!this.observer) {\n      this.timer = self.setInterval(this.detectPlayerSize.bind(this), 1000);\n    }\n    this.detectPlayerSize();\n  }\n\n  stopCapping() {\n    this.restrictedLevels = [];\n    this.autoLevelCapping = Number.POSITIVE_INFINITY;\n    if (this.timer) {\n      self.clearInterval(this.timer);\n      this.timer = undefined;\n    }\n    if (this.observer) {\n      this.observer.disconnect();\n      this.observer = undefined;\n    }\n  }\n\n  getDimensions(): { width: number; height: number } {\n    if (this.clientRect) {\n      return this.clientRect;\n    }\n    const media = this.media;\n    const boundsRect = {\n      width: 0,\n      height: 0,\n    };\n\n    if (media) {\n      const clientRect = media.getBoundingClientRect();\n      boundsRect.width = clientRect.width;\n      boundsRect.height = clientRect.height;\n      if (!boundsRect.width && !boundsRect.height) {\n        // When the media element has no width or height (equivalent to not being in the DOM),\n        // then use its width and height attributes (media.width, media.height)\n        boundsRect.width =\n          clientRect.right - clientRect.left || media.width || 0;\n        boundsRect.height =\n          clientRect.bottom - clientRect.top || media.height || 0;\n      }\n    }\n    this.clientRect = boundsRect;\n    return boundsRect;\n  }\n\n  get mediaWidth(): number {\n    return this.getDimensions().width * this.contentScaleFactor;\n  }\n\n  get mediaHeight(): number {\n    return this.getDimensions().height * this.contentScaleFactor;\n  }\n\n  get contentScaleFactor(): number {\n    let pixelRatio = 1;\n    if (!this.hls) {\n      return pixelRatio;\n    }\n    const { ignoreDevicePixelRatio, maxDevicePixelRatio } = this.hls.config;\n    if (!ignoreDevicePixelRatio) {\n      try {\n        pixelRatio = self.devicePixelRatio;\n      } catch (e) {\n        /* no-op */\n      }\n    }\n    return Math.min(pixelRatio, maxDevicePixelRatio);\n  }\n\n  private isLevelAllowed(level: Level): boolean {\n    const restrictedLevels = this.restrictedLevels;\n    return !restrictedLevels.some((restrictedLevel) => {\n      return (\n        level.bitrate === restrictedLevel.bitrate &&\n        level.width === restrictedLevel.width &&\n        level.height === restrictedLevel.height\n      );\n    });\n  }\n\n  static getMaxLevelByMediaSize(\n    levels: Array<Level>,\n    width: number,\n    height: number,\n  ): number {\n    if (!levels?.length) {\n      return -1;\n    }\n\n    // Levels can have the same dimensions but differing bandwidths - since levels are ordered, we can look to the next\n    // to determine whether we've chosen the greatest bandwidth for the media's dimensions\n    const atGreatestBandwidth = (\n      curLevel: Level,\n      nextLevel: Level | undefined,\n    ) => {\n      if (!nextLevel) {\n        return true;\n      }\n\n      return (\n        curLevel.width !== nextLevel.width ||\n        curLevel.height !== nextLevel.height\n      );\n    };\n\n    // If we run through the loop without breaking, the media's dimensions are greater than every level, so default to\n    // the max level\n    let maxLevelIndex = levels.length - 1;\n    // Prevent changes in aspect-ratio from causing capping to toggle back and forth\n    const squareSize = Math.max(width, height);\n    for (let i = 0; i < levels.length; i += 1) {\n      const level = levels[i];\n      if (\n        (level.width >= squareSize || level.height >= squareSize) &&\n        atGreatestBandwidth(level, levels[i + 1])\n      ) {\n        maxLevelIndex = i;\n        break;\n      }\n    }\n\n    return maxLevelIndex;\n  }\n}\n\nexport default CapLevelController;\n","import { ErrorActionFlags, NetworkErrorAction } from './error-controller';\nimport { ErrorDetails } from '../errors';\nimport { Events } from '../events';\nimport { Level } from '../types/level';\nimport {\n  type Loader,\n  type LoaderCallbacks,\n  type LoaderConfiguration,\n  type LoaderContext,\n  LoaderContextType,\n  type LoaderResponse,\n  type LoaderStats,\n  type PlaylistContextType,\n} from '../types/loader';\nimport { AttrList } from '../utils/attr-list';\nimport { reassignFragmentLevelIndexes } from '../utils/level-helper';\nimport { Logger } from '../utils/logger';\nimport { stringify } from '../utils/safe-json-stringify';\nimport { setQueryParam } from '../utils/url-tools';\nimport type { RetryConfig } from '../config';\nimport type Hls from '../hls';\nimport type { NetworkComponentAPI } from '../types/component-api';\nimport type {\n  ErrorData,\n  ManifestLoadedData,\n  ManifestParsedData,\n  SteeringManifestLoadedData,\n} from '../types/events';\nimport type { MediaAttributes, MediaPlaylist } from '../types/media-playlist';\nimport type { NullableNetworkDetails } from '../types/network-details';\n\nexport type SteeringManifest = {\n  VERSION: 1;\n  TTL: number;\n  'RELOAD-URI'?: string;\n  'PATHWAY-PRIORITY': string[];\n  'PATHWAY-CLONES'?: PathwayClone[];\n};\n\nexport type PathwayClone = {\n  'BASE-ID': string;\n  ID: string;\n  'URI-REPLACEMENT': UriReplacement;\n};\n\nexport type UriReplacement = {\n  HOST?: string;\n  PARAMS?: { [queryParameter: string]: string };\n  'PER-VARIANT-URIS'?: { [stableVariantId: string]: string };\n  'PER-RENDITION-URIS'?: { [stableRenditionId: string]: string };\n};\n\nconst PATHWAY_PENALTY_DURATION_MS = 300000;\n\nexport default class ContentSteeringController\n  extends Logger\n  implements NetworkComponentAPI\n{\n  private readonly hls: Hls;\n  private loader: Loader<LoaderContext> | null = null;\n  private uri: string | null = null;\n  private pathwayId: string = '.';\n  private _pathwayPriority: string[] | null = null;\n  private timeToLoad: number = 300;\n  private reloadTimer: number = -1;\n  private updated: number = 0;\n  private started: boolean = false;\n  private enabled: boolean = true;\n  private levels: Level[] | null = null;\n  private audioTracks: MediaPlaylist[] | null = null;\n  private subtitleTracks: MediaPlaylist[] | null = null;\n  private penalizedPathways: { [pathwayId: string]: number } = {};\n\n  constructor(hls: Hls) {\n    super('content-steering', hls.logger);\n    this.hls = hls;\n    this.registerListeners();\n  }\n\n  private registerListeners() {\n    const hls = this.hls;\n    hls.on(Events.MANIFEST_LOADING, this.onManifestLoading, this);\n    hls.on(Events.MANIFEST_LOADED, this.onManifestLoaded, this);\n    hls.on(Events.MANIFEST_PARSED, this.onManifestParsed, this);\n    hls.on(Events.ERROR, this.onError, this);\n  }\n\n  private unregisterListeners() {\n    const hls = this.hls;\n    if (!hls) {\n      return;\n    }\n    hls.off(Events.MANIFEST_LOADING, this.onManifestLoading, this);\n    hls.off(Events.MANIFEST_LOADED, this.onManifestLoaded, this);\n    hls.off(Events.MANIFEST_PARSED, this.onManifestParsed, this);\n    hls.off(Events.ERROR, this.onError, this);\n  }\n\n  pathways() {\n    return (this.levels || []).reduce((pathways, level) => {\n      if (pathways.indexOf(level.pathwayId) === -1) {\n        pathways.push(level.pathwayId);\n      }\n      return pathways;\n    }, [] as string[]);\n  }\n\n  get pathwayPriority(): string[] | null {\n    return this._pathwayPriority;\n  }\n\n  set pathwayPriority(pathwayPriority: string[]) {\n    this.updatePathwayPriority(pathwayPriority);\n  }\n\n  startLoad() {\n    this.started = true;\n    this.clearTimeout();\n    if (this.enabled && this.uri) {\n      if (this.updated) {\n        const ttl = this.timeToLoad * 1000 - (performance.now() - this.updated);\n        if (ttl > 0) {\n          this.scheduleRefresh(this.uri, ttl);\n          return;\n        }\n      }\n      this.loadSteeringManifest(this.uri);\n    }\n  }\n\n  stopLoad() {\n    this.started = false;\n    if (this.loader) {\n      this.loader.destroy();\n      this.loader = null;\n    }\n    this.clearTimeout();\n  }\n\n  clearTimeout() {\n    if (this.reloadTimer !== -1) {\n      self.clearTimeout(this.reloadTimer);\n      this.reloadTimer = -1;\n    }\n  }\n\n  destroy() {\n    this.unregisterListeners();\n    this.stopLoad();\n    // @ts-ignore\n    this.hls = null;\n    this.levels = this.audioTracks = this.subtitleTracks = null;\n  }\n\n  removeLevel(levelToRemove: Level) {\n    const levels = this.levels;\n    if (levels) {\n      this.levels = levels.filter((level) => level !== levelToRemove);\n    }\n  }\n\n  private onManifestLoading() {\n    this.stopLoad();\n    this.enabled = true;\n    this.timeToLoad = 300;\n    this.updated = 0;\n    this.uri = null;\n    this.pathwayId = '.';\n    this.levels = this.audioTracks = this.subtitleTracks = null;\n  }\n\n  private onManifestLoaded(\n    event: Events.MANIFEST_LOADED,\n    data: ManifestLoadedData,\n  ) {\n    const { contentSteering } = data;\n    if (contentSteering === null) {\n      return;\n    }\n    this.pathwayId = contentSteering.pathwayId;\n    this.uri = contentSteering.uri;\n    if (this.started) {\n      this.startLoad();\n    }\n  }\n\n  private onManifestParsed(\n    event: Events.MANIFEST_PARSED,\n    data: ManifestParsedData,\n  ) {\n    this.audioTracks = data.audioTracks;\n    this.subtitleTracks = data.subtitleTracks;\n  }\n\n  private onError(event: Events.ERROR, data: ErrorData) {\n    const { errorAction } = data;\n    if (\n      errorAction?.action === NetworkErrorAction.SendAlternateToPenaltyBox &&\n      errorAction.flags & ErrorActionFlags.MoveAllAlternatesMatchingHost\n    ) {\n      const levels = this.levels;\n      let pathwayPriority = this._pathwayPriority;\n      let errorPathway = this.pathwayId;\n      if (data.context) {\n        const { groupId, pathwayId, type } = data.context;\n        if (groupId && levels) {\n          errorPathway = this.getPathwayForGroupId(groupId, type, errorPathway);\n        } else if (pathwayId) {\n          errorPathway = pathwayId;\n        }\n      }\n      if (!(errorPathway in this.penalizedPathways)) {\n        this.penalizedPathways[errorPathway] = performance.now();\n      }\n      if (!pathwayPriority && levels) {\n        // If PATHWAY-PRIORITY was not provided, list pathways for error handling\n        pathwayPriority = this.pathways();\n      }\n      if (pathwayPriority && pathwayPriority.length > 1) {\n        this.updatePathwayPriority(pathwayPriority);\n        errorAction.resolved = this.pathwayId !== errorPathway;\n\n        if (\n          !errorAction.resolved &&\n          (data.details !== ErrorDetails.BUFFER_APPEND_ERROR || data.fatal)\n        ) {\n          this.warn(\n            `Could not resolve ${data.details} (\"${\n              data.error.message\n            }\") with content-steering for Pathway: ${errorPathway} levels: ${\n              levels ? levels.length : levels\n            } priorities: ${stringify(\n              pathwayPriority,\n            )} penalized: ${stringify(this.penalizedPathways)}`,\n          );\n        }\n      }\n    }\n  }\n\n  public filterParsedLevels(levels: Level[]): Level[] {\n    // Filter levels to only include those that are in the initial pathway\n    this.levels = levels;\n    let pathwayLevels = this.getLevelsForPathway(this.pathwayId);\n    if (pathwayLevels.length === 0) {\n      const pathwayId = levels[0].pathwayId;\n      this.log(\n        `No levels found in Pathway ${this.pathwayId}. Setting initial Pathway to \"${pathwayId}\"`,\n      );\n      pathwayLevels = this.getLevelsForPathway(pathwayId);\n      this.pathwayId = pathwayId;\n    }\n    if (pathwayLevels.length !== levels.length) {\n      this.log(\n        `Found ${pathwayLevels.length}/${levels.length} levels in Pathway \"${this.pathwayId}\"`,\n      );\n    }\n    return pathwayLevels;\n  }\n\n  private getLevelsForPathway(pathwayId: string): Level[] {\n    if (this.levels === null) {\n      return [];\n    }\n    return this.levels.filter((level) => pathwayId === level.pathwayId);\n  }\n\n  private updatePathwayPriority(pathwayPriority: string[]) {\n    this._pathwayPriority = pathwayPriority;\n    let levels: Level[] | undefined;\n\n    // Evaluate if we should remove the pathway from the penalized list\n    const penalizedPathways = this.penalizedPathways;\n    const now = performance.now();\n    Object.keys(penalizedPathways).forEach((pathwayId) => {\n      if (now - penalizedPathways[pathwayId] > PATHWAY_PENALTY_DURATION_MS) {\n        delete penalizedPathways[pathwayId];\n      }\n    });\n    for (let i = 0; i < pathwayPriority.length; i++) {\n      const pathwayId = pathwayPriority[i];\n      if (pathwayId in penalizedPathways) {\n        continue;\n      }\n      if (pathwayId === this.pathwayId) {\n        return;\n      }\n      const selectedIndex = this.hls.nextLoadLevel;\n      const selectedLevel: Level = this.hls.levels[selectedIndex];\n      levels = this.getLevelsForPathway(pathwayId);\n      if (levels.length > 0) {\n        this.log(`Setting Pathway to \"${pathwayId}\"`);\n        this.pathwayId = pathwayId;\n        reassignFragmentLevelIndexes(levels);\n        this.hls.trigger(Events.LEVELS_UPDATED, { levels });\n        // Set LevelController's level to trigger LEVEL_SWITCHING which loads playlist if needed\n        const levelAfterChange = this.hls.levels[selectedIndex];\n        if (selectedLevel && levelAfterChange && this.levels) {\n          if (\n            levelAfterChange.attrs['STABLE-VARIANT-ID'] !==\n              selectedLevel.attrs['STABLE-VARIANT-ID'] &&\n            levelAfterChange.bitrate !== selectedLevel.bitrate\n          ) {\n            this.log(\n              `Unstable Pathways change from bitrate ${selectedLevel.bitrate} to ${levelAfterChange.bitrate}`,\n            );\n          }\n          this.hls.nextLoadLevel = selectedIndex;\n        }\n        break;\n      }\n    }\n  }\n\n  private getPathwayForGroupId(\n    groupId: string,\n    type: PlaylistContextType,\n    defaultPathway: string,\n  ): string {\n    const levels = this.getLevelsForPathway(defaultPathway).concat(\n      this.levels || [],\n    );\n    for (let i = 0; i < levels.length; i++) {\n      if (\n        (type === LoaderContextType.AUDIO_TRACK &&\n          levels[i].hasAudioGroup(groupId)) ||\n        (type === LoaderContextType.SUBTITLE_TRACK &&\n          levels[i].hasSubtitleGroup(groupId))\n      ) {\n        return levels[i].pathwayId;\n      }\n    }\n    return defaultPathway;\n  }\n\n  private clonePathways(pathwayClones: PathwayClone[]) {\n    const levels = this.levels;\n    if (!levels) {\n      return;\n    }\n    const audioGroupCloneMap: Record<string, string> = {};\n    const subtitleGroupCloneMap: Record<string, string> = {};\n    pathwayClones.forEach((pathwayClone) => {\n      const {\n        ID: cloneId,\n        'BASE-ID': baseId,\n        'URI-REPLACEMENT': uriReplacement,\n      } = pathwayClone;\n      if (levels.some((level) => level.pathwayId === cloneId)) {\n        return;\n      }\n      const clonedVariants = this.getLevelsForPathway(baseId).map(\n        (baseLevel) => {\n          const attributes = new AttrList(baseLevel.attrs);\n          attributes['PATHWAY-ID'] = cloneId;\n          const clonedAudioGroupId: string | undefined =\n            attributes.AUDIO && `${attributes.AUDIO}_clone_${cloneId}`;\n          const clonedSubtitleGroupId: string | undefined =\n            attributes.SUBTITLES && `${attributes.SUBTITLES}_clone_${cloneId}`;\n          if (clonedAudioGroupId) {\n            audioGroupCloneMap[attributes.AUDIO] = clonedAudioGroupId;\n            attributes.AUDIO = clonedAudioGroupId;\n          }\n          if (clonedSubtitleGroupId) {\n            subtitleGroupCloneMap[attributes.SUBTITLES] = clonedSubtitleGroupId;\n            attributes.SUBTITLES = clonedSubtitleGroupId;\n          }\n          const url = performUriReplacement(\n            baseLevel.uri,\n            attributes['STABLE-VARIANT-ID'],\n            'PER-VARIANT-URIS',\n            uriReplacement,\n          );\n          const clonedLevel = new Level({\n            attrs: attributes,\n            audioCodec: baseLevel.audioCodec,\n            bitrate: baseLevel.bitrate,\n            height: baseLevel.height,\n            name: baseLevel.name,\n            url,\n            videoCodec: baseLevel.videoCodec,\n            width: baseLevel.width,\n          });\n          if (baseLevel.audioGroups) {\n            for (let i = 1; i < baseLevel.audioGroups.length; i++) {\n              clonedLevel.addGroupId(\n                'audio',\n                `${baseLevel.audioGroups[i]}_clone_${cloneId}`,\n              );\n            }\n          }\n          if (baseLevel.subtitleGroups) {\n            for (let i = 1; i < baseLevel.subtitleGroups.length; i++) {\n              clonedLevel.addGroupId(\n                'text',\n                `${baseLevel.subtitleGroups[i]}_clone_${cloneId}`,\n              );\n            }\n          }\n          return clonedLevel;\n        },\n      );\n      levels.push(...clonedVariants);\n      cloneRenditionGroups(\n        this.audioTracks,\n        audioGroupCloneMap,\n        uriReplacement,\n        cloneId,\n      );\n      cloneRenditionGroups(\n        this.subtitleTracks,\n        subtitleGroupCloneMap,\n        uriReplacement,\n        cloneId,\n      );\n    });\n  }\n\n  private loadSteeringManifest(uri: string) {\n    const config = this.hls.config;\n    const Loader = config.loader;\n    if (this.loader) {\n      this.loader.destroy();\n    }\n    this.loader = new Loader(config) as Loader<LoaderContext>;\n\n    let url: URL;\n    try {\n      url = new self.URL(uri);\n    } catch (error) {\n      this.enabled = false;\n      this.log(`Failed to parse Steering Manifest URI: ${uri}`);\n      return;\n    }\n    if (url.protocol !== 'data:') {\n      const throughput =\n        (this.hls.bandwidthEstimate || config.abrEwmaDefaultEstimate) | 0;\n      setQueryParam(url, '_HLS_pathway', this.pathwayId);\n      setQueryParam(url, '_HLS_throughput', '' + throughput);\n    }\n    const context: LoaderContext = {\n      type: LoaderContextType.STEERING_MANIFEST,\n      responseType: 'json',\n      url: url.href,\n    };\n\n    const loadPolicy = config.steeringManifestLoadPolicy.default;\n    const legacyRetryCompatibility: RetryConfig | Record<string, void> =\n      loadPolicy.errorRetry || loadPolicy.timeoutRetry || {};\n    const loaderConfig: LoaderConfiguration = {\n      loadPolicy,\n      timeout: loadPolicy.maxLoadTimeMs,\n      maxRetry: legacyRetryCompatibility.maxNumRetry || 0,\n      retryDelay: legacyRetryCompatibility.retryDelayMs || 0,\n      maxRetryDelay: legacyRetryCompatibility.maxRetryDelayMs || 0,\n    };\n\n    const callbacks: LoaderCallbacks<LoaderContext> = {\n      onSuccess: (\n        response: LoaderResponse,\n        stats: LoaderStats,\n        context: LoaderContext,\n        networkDetails: NullableNetworkDetails,\n      ) => {\n        this.log(`Loaded steering manifest: \"${url}\"`);\n        const steeringData = response.data as SteeringManifest;\n        if (steeringData?.VERSION !== 1) {\n          this.log(`Steering VERSION ${steeringData.VERSION} not supported!`);\n          return;\n        }\n        this.updated = performance.now();\n        this.timeToLoad = steeringData.TTL;\n        const {\n          'RELOAD-URI': reloadUri,\n          'PATHWAY-CLONES': pathwayClones,\n          'PATHWAY-PRIORITY': pathwayPriority,\n        } = steeringData;\n        if (reloadUri) {\n          try {\n            this.uri = new self.URL(reloadUri, url).href;\n          } catch (error) {\n            this.enabled = false;\n            this.log(\n              `Failed to parse Steering Manifest RELOAD-URI: ${reloadUri}`,\n            );\n            return;\n          }\n        }\n        this.scheduleRefresh(this.uri || context.url);\n        if (pathwayClones) {\n          this.clonePathways(pathwayClones);\n        }\n\n        const loadedSteeringData: SteeringManifestLoadedData = {\n          steeringManifest: steeringData,\n          url: url.toString(),\n        };\n        this.hls.trigger(Events.STEERING_MANIFEST_LOADED, loadedSteeringData);\n\n        if (pathwayPriority) {\n          this.updatePathwayPriority(pathwayPriority);\n        }\n      },\n\n      onError: (\n        error: { code: number; text: string },\n        context: LoaderContext,\n        networkDetails: NullableNetworkDetails,\n        stats: LoaderStats,\n      ) => {\n        this.log(\n          `Error loading steering manifest: ${error.code} ${error.text} (${context.url})`,\n        );\n        this.stopLoad();\n        if (error.code === 410) {\n          this.enabled = false;\n          this.log(`Steering manifest ${context.url} no longer available`);\n          return;\n        }\n        let ttl = this.timeToLoad * 1000;\n        if (error.code === 429) {\n          const loader = this.loader;\n          if (typeof loader?.getResponseHeader === 'function') {\n            const retryAfter = loader.getResponseHeader('Retry-After');\n            if (retryAfter) {\n              ttl = parseFloat(retryAfter) * 1000;\n            }\n          }\n          this.log(`Steering manifest ${context.url} rate limited`);\n          return;\n        }\n        this.scheduleRefresh(this.uri || context.url, ttl);\n      },\n\n      onTimeout: (\n        stats: LoaderStats,\n        context: LoaderContext,\n        networkDetails: NullableNetworkDetails,\n      ) => {\n        this.log(`Timeout loading steering manifest (${context.url})`);\n        this.scheduleRefresh(this.uri || context.url);\n      },\n    };\n\n    this.log(`Requesting steering manifest: ${url}`);\n    this.loader.load(context, loaderConfig, callbacks);\n  }\n\n  private scheduleRefresh(uri: string, ttlMs: number = this.timeToLoad * 1000) {\n    this.clearTimeout();\n    this.reloadTimer = self.setTimeout(() => {\n      const media = this.hls?.media;\n      if (media && !media.ended) {\n        this.loadSteeringManifest(uri);\n        return;\n      }\n      this.scheduleRefresh(uri, this.timeToLoad * 1000);\n    }, ttlMs);\n  }\n}\n\nfunction cloneRenditionGroups(\n  tracks: MediaPlaylist[] | null,\n  groupCloneMap: Record<string, string>,\n  uriReplacement: UriReplacement,\n  cloneId: string,\n) {\n  if (!tracks) {\n    return;\n  }\n  Object.keys(groupCloneMap).forEach((audioGroupId) => {\n    const clonedTracks = tracks\n      .filter((track) => track.groupId === audioGroupId)\n      .map((track) => {\n        const clonedTrack = Object.assign({}, track);\n        clonedTrack.details = undefined;\n        clonedTrack.attrs = new AttrList(clonedTrack.attrs) as MediaAttributes;\n        clonedTrack.url = clonedTrack.attrs.URI = performUriReplacement(\n          track.url,\n          track.attrs['STABLE-RENDITION-ID'],\n          'PER-RENDITION-URIS',\n          uriReplacement,\n        );\n        clonedTrack.groupId = clonedTrack.attrs['GROUP-ID'] =\n          groupCloneMap[audioGroupId];\n        clonedTrack.attrs['PATHWAY-ID'] = cloneId;\n        return clonedTrack;\n      });\n    tracks.push(...clonedTracks);\n  });\n}\n\nfunction performUriReplacement(\n  uri: string,\n  stableId: string | undefined,\n  perOptionKey: 'PER-VARIANT-URIS' | 'PER-RENDITION-URIS',\n  uriReplacement: UriReplacement,\n): string {\n  if (stableId) {\n    const { [perOptionKey]: perOptionUris } = uriReplacement;\n    if (perOptionUris) {\n      const perVariantUri = perOptionUris[stableId];\n      if (perVariantUri) {\n        return perVariantUri;\n      }\n    }\n  }\n  const { HOST: host, PARAMS: params } = uriReplacement;\n  const url = new self.URL(uri);\n  if (host) {\n    url.hostname = host;\n  }\n  if (params) {\n    Object.keys(params)\n      .sort()\n      .forEach((key) => {\n        if (key) {\n          setQueryParam(url, key, params[key]);\n        }\n      });\n  }\n  return url.href;\n}\n","import { Events } from '../events';\nimport type StreamController from './stream-controller';\nimport type Hls from '../hls';\nimport type { ComponentAPI } from '../types/component-api';\nimport type { MediaAttachingData } from '../types/events';\n\nclass FPSController implements ComponentAPI {\n  private hls: Hls;\n  private isVideoPlaybackQualityAvailable: boolean = false;\n  private timer?: number;\n  private media: HTMLVideoElement | null = null;\n  private lastTime: any;\n  private lastDroppedFrames: number = 0;\n  private lastDecodedFrames: number = 0;\n  // stream controller must be provided as a dependency!\n  private streamController!: StreamController;\n\n  constructor(hls: Hls) {\n    this.hls = hls;\n\n    this.registerListeners();\n  }\n\n  public setStreamController(streamController: StreamController) {\n    this.streamController = streamController;\n  }\n\n  protected registerListeners() {\n    this.hls.on(Events.MEDIA_ATTACHING, this.onMediaAttaching, this);\n    this.hls.on(Events.MEDIA_DETACHING, this.onMediaDetaching, this);\n  }\n\n  protected unregisterListeners() {\n    this.hls.off(Events.MEDIA_ATTACHING, this.onMediaAttaching, this);\n    this.hls.off(Events.MEDIA_DETACHING, this.onMediaDetaching, this);\n  }\n\n  destroy() {\n    if (this.timer) {\n      clearInterval(this.timer);\n    }\n\n    this.unregisterListeners();\n    this.isVideoPlaybackQualityAvailable = false;\n    this.media = null;\n  }\n\n  protected onMediaAttaching(\n    event: Events.MEDIA_ATTACHING,\n    data: MediaAttachingData,\n  ) {\n    const config = this.hls.config;\n    if (config.capLevelOnFPSDrop) {\n      const media =\n        data.media i